INSERT IGNORE INTO `pages` (`slug`, `template`, `nav_order`, `status`, `published_at`) VALUES ('about/concession', 'default', 0, 'published', CURRENT_TIMESTAMP);
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'en', 'Concession and financing', 'The terms under which DBEDC builds, operates and hands back the Dhaka Bypass Expressway, and how it is financed.', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'bn', 'কনসেশন ও অর্থায়ন', 'যে শর্তে DBEDC ঢাকা বাইপাস এক্সপ্রেসওয়ে নির্মাণ, পরিচালনা ও হস্তান্তর করে এবং এর অর্থায়ন কীভাবে হয়।', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'zh', '特许经营与融资', 'DBEDC建设、运营并移交达卡绕城高速公路所依据的条款及其融资方式。', 'published');
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'page-header', 0, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"eyebrow":"About DBEDC","heading":"Concession and financing","lede":"The Dhaka Bypass Expressway is a public–private partnership: the Government grants the concession, DBEDC builds, finances, operates and maintains the road, and hands it back at the end of the term."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"DBEDC পরিচিতি","heading":"কনসেশন ও অর্থায়ন","lede":"ঢাকা বাইপাস এক্সপ্রেসওয়ে একটি সরকারি-বেসরকারি অংশীদারিত্ব প্রকল্প: সরকার কনসেশন দেয়, DBEDC সড়কটি নির্মাণ, অর্থায়ন, পরিচালনা ও রক্ষণাবেক্ষণ করে এবং মেয়াদ শেষে তা ফেরত দেয়।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"关于DBEDC","heading":"特许经营与融资","lede":"达卡绕城高速公路是政府与社会资本合作项目：政府授予特许经营权，DBEDC负责建设、融资、运营和养护，期满后移交。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'card-grid', 1, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Key terms","intro":"","items":[{"meta":"Signed","title":"6 December 2018","body":"Concession agreement between the Roads and Highways Department and the concessionaire."},{"meta":"Model","title":"DBFOMT","body":"Design, build, finance, operate, maintain and transfer."},{"meta":"Term","title":"25 years","body":"The concession period set by the agreement, including construction and operation."},{"meta":"Grantor","title":"Roads and Highways Department","body":"The contracting authority under the Road Transport and Highways Division; it monitors compliance through its Project Director."},{"meta":"Concessionaire","title":"DBEDC","body":"The project company formed by Sichuan Road & Bridge Group, Shamim Enterprise and UDC Construction."},{"meta":"Handback","title":"To the Government","body":"At the end of the term the expressway returns to the Roads and Highways Department in the condition the agreement requires."}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"মূল শর্তাবলি","intro":"","items":[{"meta":"স্বাক্ষর","title":"৬ ডিসেম্বর ২০১৮","body":"সড়ক ও জনপথ অধিদপ্তর এবং কনসেশনগ্রহীতার মধ্যে কনসেশন চুক্তি।"},{"meta":"মডেল","title":"DBFOMT","body":"নকশা, নির্মাণ, অর্থায়ন, পরিচালনা, রক্ষণাবেক্ষণ ও হস্তান্তর।"},{"meta":"মেয়াদ","title":"২৫ বছর","body":"চুক্তিতে নির্ধারিত কনসেশন মেয়াদ, নির্মাণ ও পরিচালনাসহ।"},{"meta":"প্রদানকারী","title":"সড়ক ও জনপথ অধিদপ্তর","body":"সড়ক পরিবহন ও মহাসড়ক বিভাগের অধীন চুক্তিকারী কর্তৃপক্ষ; প্রকল্প পরিচালকের মাধ্যমে চুক্তি পরিপালন তদারক করে।"},{"meta":"কনসেশনগ্রহীতা","title":"DBEDC","body":"সিচুয়ান রোড অ্যান্ড ব্রিজ গ্রুপ, শামীম এন্টারপ্রাইজ ও ইউডিসি কনস্ট্রাকশনের গঠিত প্রকল্প কোম্পানি।"},{"meta":"হস্তান্তর","title":"সরকারের কাছে","body":"মেয়াদ শেষে এক্সপ্রেসওয়েটি চুক্তিতে নির্ধারিত অবস্থায় সড়ক ও জনপথ অধিদপ্তরের কাছে ফেরত যায়।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"主要条款","intro":"","items":[{"meta":"签署","title":"2018年12月6日","body":"孟加拉国公路局与特许经营方签订特许经营协议。"},{"meta":"模式","title":"DBFOMT","body":"设计、建设、融资、运营、维护和移交。"},{"meta":"期限","title":"25年","body":"协议规定的特许经营期，含建设期和运营期。"},{"meta":"授予方","title":"孟加拉国公路局","body":"道路交通与公路司下属的合同授予机构，通过项目主任监督协议履行。"},{"meta":"特许经营方","title":"DBEDC","body":"由四川路桥集团、Shamim Enterprise和UDC Construction组建的项目公司。"},{"meta":"移交","title":"移交政府","body":"期满后，高速公路按协议要求的状态移交孟加拉国公路局。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"How tolls are set and revised","body":"<p>Toll rates on the expressway are fixed by government notification, not by DBEDC. DBEDC collects the rates in force and publishes them, by vehicle class, on the <a href=\\"travel/toll\\">toll rates</a> page. A revision takes effect only when a new notification is issued; the date each rate took effect is shown with the schedule, and the notifications themselves are listed on the <a href=\\"disclosures/tariff\\">tariff notifications</a> page.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"টোল কীভাবে নির্ধারণ ও সংশোধন হয়","body":"<p>এক্সপ্রেসওয়ের টোল হার DBEDC নয়, সরকারি প্রজ্ঞাপনের মাধ্যমে নির্ধারিত হয়। DBEDC কার্যকর হার আদায় করে এবং যানবাহনের শ্রেণি অনুযায়ী <a href=\\"travel/toll\\">টোল হার</a> পাতায় প্রকাশ করে। নতুন প্রজ্ঞাপন জারি হলেই কেবল সংশোধন কার্যকর হয়; প্রতিটি হার কবে থেকে কার্যকর তা তালিকার সঙ্গে দেখানো হয় এবং প্রজ্ঞাপনগুলো <a href=\\"disclosures/tariff\\">টোল প্রজ্ঞাপন</a> পাতায় তালিকাভুক্ত।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"通行费如何制定和调整","body":"<p>快速路通行费标准由政府公告确定，而非由DBEDC自行制定。DBEDC按现行标准收费，并在<a href=\\"travel/toll\\">通行费标准</a>页面按车型公布。只有新公告发布后调整才生效；每项费率的生效日期随收费表显示，相关公告列于<a href=\\"disclosures/tariff\\">收费公告</a>页面。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 3, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Financing and the PPPA record","body":"<p>The project is financed by the shareholders'' equity, loans from China Development Bank and Bangladesh Infrastructure Finance Fund Limited, and viability gap funding from the Government. The amounts and the lenders are set out on the <a href=\\"about/governance\\">governance</a> page.</p><p>The Public-Private Partnership Authority maintains the official project profile, including the project''s place in the national PPP pipeline: <a href=\\"https://www.pppo.gov.bd/projects-dhaka-bypass.php\\">PPPA — Dhaka Bypass</a>.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"অর্থায়ন ও PPPA-র নথি","body":"<p>প্রকল্পটির অর্থায়ন হয়েছে শেয়ারহোল্ডারদের ইকুইটি, চায়না ডেভেলপমেন্ট ব্যাংক ও বাংলাদেশ ইনফ্রাস্ট্রাকচার ফাইন্যান্স ফান্ড লিমিটেডের ঋণ এবং সরকারের ভায়াবিলিটি গ্যাপ ফান্ডিং থেকে। অর্থের পরিমাণ ও ঋণদাতাদের বিবরণ <a href=\\"about/governance\\">পরিচালনা কাঠামো</a> পাতায় দেওয়া আছে।</p><p>পাবলিক-প্রাইভেট পার্টনারশিপ কর্তৃপক্ষ প্রকল্পের দাপ্তরিক পরিচিতি সংরক্ষণ করে, জাতীয় পিপিপি তালিকায় প্রকল্পের অবস্থানসহ: <a href=\\"https://www.pppo.gov.bd/projects-dhaka-bypass.php\\">PPPA — ঢাকা বাইপাস</a>।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"融资与PPPA记录","body":"<p>项目资金来源包括股东股本、国家开发银行和孟加拉国基础设施融资基金有限公司的贷款，以及政府的可行性缺口补助。具体金额和贷款方见<a href=\\"about/governance\\">治理结构</a>页面。</p><p>政府与社会资本合作管理局维护项目官方资料，包括项目在国家PPP项目库中的情况：<a href=\\"https://www.pppo.gov.bd/projects-dhaka-bypass.php\\">PPPA——达卡绕城公路</a>。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'cta-band', 4, 'published' FROM DUAL WHERE @fresh = 1;
