INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"কে কী করে","body":"অংশীদার, ঋণদাতা ও পরিচালনা কাঠামো।","primaryLabel":"পরিচালনা কাঠামো","primaryHref":"about/governance","secondaryLabel":"টোল প্রজ্ঞাপন","secondaryHref":"disclosures/tariff"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
