INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"DBEDC পরিচিতি","heading":"DBEDC-এর সাংগঠনিক কাঠামো","lede":"পর্ষদ থেকে সড়কের দল পর্যন্ত — এক্সপ্রেসওয়ে নির্মাণ, পরিচালনা ও রক্ষণাবেক্ষণের দায়িত্ব কার।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
