INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Departments","intro":"Each department reports to the Chief Executive Officer, who is accountable to the Board of Directors.","items":[{"meta":"Operations","title":"Toll operations","body":"Toll plazas, collection, receipts, disputes at the barrier and the accuracy of vehicle classification."},{"meta":"Operations","title":"Traffic management and patrol","body":"Incident response, breakdown recovery, lane closures, advisories and the control room."},{"meta":"Engineering","title":"Maintenance","body":"Pavement, structures, drainage, lighting, signs and barriers, to the standards the concession sets."},{"meta":"Engineering","title":"Construction and quality","body":"Delivery of the sections still under construction and quality assurance on every section."},{"meta":"Safeguards","title":"Environment, health and safety","body":"Workforce safety, environmental management and monitoring along the corridor."},{"meta":"Corporate","title":"Finance and accounts","body":"Financial management, lender reporting and the audited accounts."},{"meta":"Corporate","title":"Procurement","body":"Tenders, supplier registration and contract management."},{"meta":"Corporate","title":"Administration, HR and legal","body":"Recruitment, staff welfare, compliance with the concession and the law, and information requests."},{"meta":"Public","title":"Customer service and grievances","body":"Enquiries, complaints, lost property and the public response times set out in the citizen charter."}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"বিভাগসমূহ","intro":"প্রতিটি বিভাগ প্রধান নির্বাহী কর্মকর্তার কাছে জবাবদিহি করে, যিনি পরিচালনা পর্ষদের কাছে দায়বদ্ধ।","items":[{"meta":"পরিচালনা","title":"টোল পরিচালনা","body":"টোল প্লাজা, টোল আদায়, রসিদ, প্লাজায় বিরোধ এবং যানবাহনের শ্রেণি নির্ধারণের নির্ভুলতা।"},{"meta":"পরিচালনা","title":"ট্রাফিক ব্যবস্থাপনা ও টহল","body":"দুর্ঘটনায় সাড়া, বিকল যানবাহন উদ্ধার, লেন বন্ধ, বিজ্ঞপ্তি ও নিয়ন্ত্রণকক্ষ।"},{"meta":"প্রকৌশল","title":"রক্ষণাবেক্ষণ","body":"কনসেশনে নির্ধারিত মান অনুযায়ী পেভমেন্ট, অবকাঠামো, নিষ্কাশন, আলো, সাইন ও ব্যারিয়ার।"},{"meta":"প্রকৌশল","title":"নির্মাণ ও মাননিয়ন্ত্রণ","body":"নির্মাণাধীন অংশগুলোর কাজ সম্পন্ন করা এবং প্রতিটি অংশে মান নিশ্চিত করা।"},{"meta":"সুরক্ষা","title":"পরিবেশ, স্বাস্থ্য ও নিরাপত্তা","body":"কর্মীদের নিরাপত্তা, পরিবেশ ব্যবস্থাপনা ও করিডোরজুড়ে পর্যবেক্ষণ।"},{"meta":"কর্পোরেট","title":"অর্থ ও হিসাব","body":"আর্থিক ব্যবস্থাপনা, ঋণদাতাদের কাছে প্রতিবেদন ও নিরীক্ষিত হিসাব।"},{"meta":"কর্পোরেট","title":"ক্রয়","body":"দরপত্র, সরবরাহকারী নিবন্ধন ও চুক্তি ব্যবস্থাপনা।"},{"meta":"কর্পোরেট","title":"প্রশাসন, মানবসম্পদ ও আইন","body":"নিয়োগ, কর্মী কল্যাণ, কনসেশন ও আইন পরিপালন এবং তথ্যের অনুরোধ।"},{"meta":"জনসেবা","title":"গ্রাহকসেবা ও অভিযোগ","body":"জিজ্ঞাসা, অভিযোগ, হারানো জিনিস এবং নাগরিক সনদে নির্ধারিত সাড়া দেওয়ার সময়।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"部门设置","intro":"各部门向首席执行官汇报，首席执行官对董事会负责。","items":[{"meta":"运营","title":"收费运营","body":"收费站、收费、票据、收费口争议及车型分类准确性。"},{"meta":"运营","title":"交通管理与巡逻","body":"事故处置、故障车救援、车道封闭、通告发布和监控中心。"},{"meta":"工程","title":"养护","body":"按特许经营标准养护路面、构造物、排水、照明、标志和护栏。"},{"meta":"工程","title":"建设与质量","body":"推进在建路段施工，并对各路段进行质量保证。"},{"meta":"保障","title":"环境、健康与安全","body":"员工安全、环境管理和走廊沿线监测。"},{"meta":"综合","title":"财务","body":"财务管理、向贷款方报告和经审计的财务报表。"},{"meta":"综合","title":"采购","body":"招标、供应商登记和合同管理。"},{"meta":"综合","title":"行政、人力资源与法务","body":"招聘、员工福利、特许经营协议和法律合规以及信息公开申请。"},{"meta":"公众","title":"客户服务与投诉","body":"咨询、投诉、失物招领以及公民宪章规定的答复时限。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Organisation chart","body":"<ul><li><strong>Board of Directors</strong> — representatives of SRBG, SEL and UDC<ul><li><strong>Chief Executive Officer</strong><ul><li>Chief Operating Officer — toll operations; traffic management and patrol; maintenance; customer service</li><li>Engineering — construction and quality; environment, health and safety</li><li>Corporate — finance and accounts; procurement; administration, HR and legal</li></ul></li></ul></li><li><strong>Roads and Highways Department</strong> — Project Director (oversight on behalf of the Government)</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"সাংগঠনিক চিত্র","body":"<ul><li><strong>পরিচালনা পর্ষদ</strong> — SRBG, SEL ও UDC-এর প্রতিনিধি<ul><li><strong>প্রধান নির্বাহী কর্মকর্তা</strong><ul><li>প্রধান পরিচালন কর্মকর্তা — টোল পরিচালনা; ট্রাফিক ব্যবস্থাপনা ও টহল; রক্ষণাবেক্ষণ; গ্রাহকসেবা</li><li>প্রকৌশল — নির্মাণ ও মাননিয়ন্ত্রণ; পরিবেশ, স্বাস্থ্য ও নিরাপত্তা</li><li>কর্পোরেট — অর্থ ও হিসাব; ক্রয়; প্রশাসন, মানবসম্পদ ও আইন</li></ul></li></ul></li><li><strong>সড়ক ও জনপথ অধিদপ্তর</strong> — প্রকল্প পরিচালক (সরকারের পক্ষে তদারকি)</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"组织结构图","body":"<ul><li><strong>董事会</strong>——SRBG、SEL和UDC的代表<ul><li><strong>首席执行官</strong><ul><li>首席运营官——收费运营；交通管理与巡逻；养护；客户服务</li><li>工程——建设与质量；环境、健康与安全</li><li>综合——财务；采购；行政、人力资源与法务</li></ul></li></ul></li><li><strong>孟加拉国公路局</strong>——项目主任（代表政府监督）</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
