INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'en', 'Careers', 'Working at DBEDC: how positions are advertised, how to apply, and how to recognise a fake job offer.', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'bn', 'ক্যারিয়ার', 'DBEDC-এ কাজ: পদ কীভাবে বিজ্ঞাপিত হয়, কীভাবে আবেদন করবেন এবং ভুয়া চাকরির প্রস্তাব কীভাবে চিনবেন।', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'zh', '招聘', '在DBEDC工作：职位如何发布、如何申请以及如何识别虚假招聘。', 'published');
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'page-header', 0, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"eyebrow":"About DBEDC","heading":"Careers","lede":"Operating a 24-hour expressway takes toll staff, patrol crews, engineers, safety officers and corporate teams."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"DBEDC পরিচিতি","heading":"ক্যারিয়ার","lede":"২৪ ঘণ্টা চালু একটি এক্সপ্রেসওয়ে পরিচালনায় টোলকর্মী, টহল দল, প্রকৌশলী, নিরাপত্তা কর্মকর্তা ও কর্পোরেট দল প্রয়োজন।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"关于DBEDC","heading":"招聘","lede":"全天候运营一条高速公路，需要收费员、巡逻队、工程师、安全员和综合管理团队。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 1, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"How we recruit","body":"<p>Every open position is advertised on this page and in national newspapers, with the closing date and how to apply. Selection is by written application, assessment and interview, on merit. DBEDC is an equal-opportunity employer, and people from the communities along the corridor are encouraged to apply.</p><p>When there are no open positions, nothing is listed here. Send a speculative application through the <a href=\\"contact\\">contact form</a> and it will be kept on file for twelve months.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"আমরা কীভাবে নিয়োগ দিই","body":"<p>প্রতিটি খালি পদ এই পাতায় ও জাতীয় দৈনিকে বিজ্ঞাপিত হয়, আবেদনের শেষ তারিখ ও আবেদনের পদ্ধতিসহ। লিখিত আবেদন, মূল্যায়ন ও সাক্ষাৎকারের মাধ্যমে মেধার ভিত্তিতে বাছাই করা হয়। DBEDC সমান সুযোগ প্রদানকারী নিয়োগকর্তা; করিডোর সংলগ্ন এলাকার মানুষদের আবেদন করতে উৎসাহিত করা হয়।</p><p>কোনো খালি পদ না থাকলে এখানে কিছু তালিকাভুক্ত থাকে না। <a href=\\"contact\\">যোগাযোগ ফরম</a> দিয়ে আগ্রহপত্র পাঠালে তা বারো মাস সংরক্ষিত থাকবে।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"招聘方式","body":"<p>所有空缺职位均在本页面及全国性报纸上发布，注明截止日期和申请方式。通过书面申请、测评和面试择优录用。DBEDC是平等机会雇主，欢迎走廊沿线社区居民申请。</p><p>无空缺职位时本页不列出职位。可通过<a href=\\"contact\\">联系表单</a>投递自荐申请，资料将保存十二个月。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Beware of fake job offers","body":"<p>DBEDC never asks for money at any stage of recruitment — not for an application form, a test, a medical check or an appointment letter — and never recruits through agents or mobile-money payments. If anyone asks you to pay for a job with DBEDC, do not pay, and report it through the <a href=\\"about/integrity\\">integrity</a> page.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"ভুয়া চাকরির প্রস্তাব থেকে সাবধান","body":"<p>DBEDC নিয়োগের কোনো ধাপে টাকা চায় না — আবেদনপত্র, পরীক্ষা, স্বাস্থ্য পরীক্ষা বা নিয়োগপত্র কোনোটির জন্যই নয় — এবং দালাল বা মোবাইল ব্যাংকিংয়ে টাকা নিয়ে নিয়োগ দেয় না। DBEDC-এ চাকরির জন্য কেউ টাকা চাইলে দেবেন না এবং <a href=\\"about/integrity\\">শুদ্ধাচার</a> পাতার মাধ্যমে জানান।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"谨防虚假招聘","body":"<p>DBEDC在招聘的任何环节都不收取任何费用——无论是申请表、考试、体检还是录用通知——也从不通过中介或移动支付招聘。如有人以DBEDC职位名义向您收费，请勿付款，并通过<a href=\\"about/integrity\\">廉洁建设</a>页面举报。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `pages` (`slug`, `template`, `nav_order`, `status`, `published_at`) VALUES ('about/integrity', 'default', 0, 'published', CURRENT_TIMESTAMP);
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'en', 'Integrity', 'DBEDC''s commitments under the National Integrity Strategy, and how to report bribery, fraud or misconduct.', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'bn', 'শুদ্ধাচার', 'জাতীয় শুদ্ধাচার কৌশলের আওতায় DBEDC-এর অঙ্গীকার এবং ঘুষ, প্রতারণা বা অসদাচরণ কীভাবে জানাবেন।', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'zh', '廉洁建设', 'DBEDC依据国家廉洁战略作出的承诺，以及如何举报贿赂、欺诈或不当行为。', 'published');
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'page-header', 0, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"eyebrow":"About DBEDC","heading":"Integrity","lede":"No one should pay more than the published toll, and no one should pay anything to get a job, a contract or a decision from DBEDC."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"DBEDC পরিচিতি","heading":"শুদ্ধাচার","lede":"প্রকাশিত টোলের বেশি কাউকে দিতে হবে না, আর DBEDC-এর কাছ থেকে চাকরি, চুক্তি বা সিদ্ধান্ত পেতে কাউকে কিছু দিতে হবে না।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"关于DBEDC","heading":"廉洁建设","lede":"任何人都不应支付超过公布标准的通行费，也不应为获得DBEDC的工作、合同或决定支付任何费用。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 1, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Our commitments","body":"<p>DBEDC works in line with the National Integrity Strategy adopted by the Government of Bangladesh in 2012, which asks public bodies and the private sector alike to adopt integrity practices. In practice that means:</p><ul><li>a published toll for every vehicle class, and a receipt for every payment;</li><li>open tenders for goods, works and services, published on the <a href=\\"procurement\\">procurement</a> page;</li><li>recruitment on merit, with no fees at any stage;</li><li>a code of conduct for every employee, including toll and patrol staff, with no gifts or cash accepted;</li><li>an integrity focal point who receives reports and follows them up, and an annual integrity action plan.</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"আমাদের অঙ্গীকার","body":"<p>DBEDC বাংলাদেশ সরকারের ২০১২ সালে গৃহীত জাতীয় শুদ্ধাচার কৌশল অনুসরণ করে, যা সরকারি প্রতিষ্ঠান ও বেসরকারি খাত উভয়কে শুদ্ধাচার চর্চা গ্রহণের আহ্বান জানায়। বাস্তবে এর অর্থ:</p><ul><li>প্রতিটি যানবাহন শ্রেণির জন্য প্রকাশিত টোল এবং প্রতিটি পরিশোধের রসিদ;</li><li>পণ্য, কাজ ও সেবার জন্য উন্মুক্ত দরপত্র, <a href=\\"procurement\\">ক্রয়</a> পাতায় প্রকাশিত;</li><li>মেধার ভিত্তিতে নিয়োগ, কোনো ধাপে কোনো ফি নেই;</li><li>টোল ও টহলকর্মীসহ প্রত্যেক কর্মীর জন্য আচরণবিধি, কোনো উপহার বা নগদ গ্রহণ নয়;</li><li>একজন শুদ্ধাচার ফোকাল পয়েন্ট, যিনি অভিযোগ গ্রহণ ও অনুসরণ করেন, এবং বার্ষিক শুদ্ধাচার কর্মপরিকল্পনা।</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"我们的承诺","body":"<p>DBEDC遵循孟加拉国政府2012年通过的《国家廉洁战略》，该战略要求公共机构和私营部门共同践行廉洁。具体包括：</p><ul><li>每类车型公布通行费标准，每笔付款提供票据；</li><li>货物、工程和服务公开招标，并在<a href=\\"procurement\\">采购</a>页面公布；</li><li>择优招聘，任何环节不收费；</li><li>全体员工（包括收费和巡逻人员）遵守行为准则，不收受礼品或现金；</li><li>设立廉洁联络人受理和跟进举报，并制定年度廉洁行动计划。</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Report a concern","body":"<p>If you were asked for money at a toll plaza, overcharged, offered or asked for a bribe, or saw fraud or misconduct by anyone working for DBEDC, report it through the <a href=\\"grievances\\">grievance form</a>. Choose the category that fits and say what happened, when and where. You will receive a tracking number, and the report is handled by someone independent of the team involved.</p><p>You can also report corruption directly to the Anti-Corruption Commission of Bangladesh on its hotline, 106.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"উদ্বেগ জানান","body":"<p>টোল প্লাজায় আপনার কাছে টাকা চাওয়া হলে, বেশি টোল নেওয়া হলে, ঘুষ চাওয়া বা প্রস্তাব করা হলে, অথবা DBEDC-এর কোনো কর্মীর প্রতারণা বা অসদাচরণ দেখলে <a href=\\"grievances\\">অভিযোগ ফরম</a> দিয়ে জানান। উপযুক্ত শ্রেণি বেছে নিয়ে কী, কখন ও কোথায় ঘটেছে তা লিখুন। আপনি একটি ট্র্যাকিং নম্বর পাবেন এবং সংশ্লিষ্ট দলের বাইরের একজন অভিযোগটি দেখবেন।</p><p>দুর্নীতির অভিযোগ সরাসরি দুর্নীতি দমন কমিশনের হটলাইন ১০৬-এও জানাতে পারেন।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"举报问题","body":"<p>如在收费站被索要钱款、被多收费、被索贿或被行贿，或发现DBEDC任何工作人员有欺诈或不当行为，请通过<a href=\\"grievances\\">投诉表单</a>举报。选择相应类别，说明事件经过、时间和地点。您将获得跟踪编号，举报由与涉事团队无关的人员处理。</p><p>您也可以直接拨打孟加拉国反腐败委员会热线106举报腐败。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
