INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"eyebrow":"Disclosures","heading":"Right to information","lede":"The Right to Information Act 2009 gives every citizen the right to ask for information. This is how to ask DBEDC, and what happens next."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"তথ্য প্রকাশ","heading":"তথ্য অধিকার","lede":"তথ্য অধিকার আইন ২০০৯ প্রত্যেক নাগরিককে তথ্য চাওয়ার অধিকার দেয়। DBEDC-এর কাছে কীভাবে চাইবেন এবং তারপর কী হয়, তা এখানে।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"信息公开","heading":"信息公开","lede":"《2009年信息权法》赋予每位公民申请信息的权利。以下说明如何向DBEDC申请以及后续流程。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 1, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Information already published","body":"<p>Much of what people ask for is already public, and you do not need to make a request to see it: <a href=\\"travel/toll\\">toll rates</a>, <a href=\\"disclosures/tariff\\">tariff notifications</a>, <a href=\\"about/concession\\">the concession</a>, <a href=\\"about/governance\\">governance and financing</a>, <a href=\\"disclosures/land-acquisition\\">land acquisition</a>, <a href=\\"procurement\\">tenders</a>, <a href=\\"disclosures/reports\\">reports</a> and <a href=\\"disclosures/policies\\">policies</a>.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"ইতিমধ্যে প্রকাশিত তথ্য","body":"<p>মানুষ যা জানতে চান তার অনেকটাই ইতিমধ্যে প্রকাশিত; দেখতে অনুরোধ করার প্রয়োজন নেই: <a href=\\"travel/toll\\">টোল হার</a>, <a href=\\"disclosures/tariff\\">টোল প্রজ্ঞাপন</a>, <a href=\\"about/concession\\">কনসেশন</a>, <a href=\\"about/governance\\">পরিচালনা ও অর্থায়ন</a>, <a href=\\"disclosures/land-acquisition\\">ভূমি অধিগ্রহণ</a>, <a href=\\"procurement\\">দরপত্র</a>, <a href=\\"disclosures/reports\\">প্রতিবেদন</a> ও <a href=\\"disclosures/policies\\">নীতিমালা</a>।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"已公开的信息","body":"<p>许多常见问题的信息已经公开，无需申请即可查看：<a href=\\"travel/toll\\">通行费标准</a>、<a href=\\"disclosures/tariff\\">收费公告</a>、<a href=\\"about/concession\\">特许经营</a>、<a href=\\"about/governance\\">治理与融资</a>、<a href=\\"disclosures/land-acquisition\\">征地</a>、<a href=\\"procurement\\">招标</a>、<a href=\\"disclosures/reports\\">报告</a>和<a href=\\"disclosures/policies\\">政策</a>。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'faq', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Making a request","intro":"","items":[{"question":"How do I ask for information?","answer":"<p>Write to DBEDC''s designated information officer through the <a href=\\"contact\\">contact form</a>, choosing the subject “Information request”, or in writing to the office. Give your name and address, describe the information you want as precisely as you can, and say how you would like to receive it (copy, email or inspection). The application form prescribed by the Information Commission may be used but is not required.</p>"},{"question":"How long does a reply take?","answer":"<p>The Act allows up to 20 working days from receipt of the request, or 30 working days when the information concerns a third party, and 24 hours when it concerns a person''s life or liberty. If a request cannot be met, you will be told why in writing.</p>"},{"question":"Is there a fee?","answer":"<p>There is no fee for making a request. Where information is supplied as copies, the reasonable cost of copying set by the Information Commission may be charged, and you will be told the amount before it is incurred.</p>"},{"question":"What if I am refused or receive no reply?","answer":"<p>You may appeal to DBEDC''s appeal authority within 30 days of the refusal or of the deadline passing; the appeal is decided within 15 days. If you remain dissatisfied, you may complain to the Information Commission of Bangladesh.</p>"},{"question":"What can be withheld?","answer":"<p>Only information the Act exempts, such as commercially confidential information whose disclosure would harm a third party''s competitive position, personal information, or information that would affect security or an investigation. Everything else is disclosable.</p>"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"অনুরোধ করা","intro":"","items":[{"question":"কীভাবে তথ্য চাইব?","answer":"<p><a href=\\"contact\\">যোগাযোগ ফরমে</a> “তথ্যের অনুরোধ” বিষয় বেছে বা অফিসে লিখিতভাবে DBEDC-এর দায়িত্বপ্রাপ্ত তথ্য কর্মকর্তার কাছে লিখুন। আপনার নাম ও ঠিকানা দিন, কী তথ্য চান যতটা সম্ভব সুনির্দিষ্টভাবে বলুন এবং কীভাবে পেতে চান (অনুলিপি, ইমেইল বা পরিদর্শন) জানান। তথ্য কমিশন নির্ধারিত আবেদন ফরম ব্যবহার করা যায়, তবে তা বাধ্যতামূলক নয়।</p>"},{"question":"উত্তর পেতে কত সময় লাগে?","answer":"<p>আইন অনুযায়ী অনুরোধ পাওয়ার পর সর্বোচ্চ ২০ কার্যদিবস, তৃতীয় পক্ষ সংশ্লিষ্ট হলে ৩০ কার্যদিবস, এবং কারও জীবন-মৃত্যু বা স্বাধীনতার বিষয় হলে ২৪ ঘণ্টা। অনুরোধ পূরণ করা না গেলে কারণ লিখিতভাবে জানানো হবে।</p>"},{"question":"কোনো ফি আছে কি?","answer":"<p>অনুরোধ করতে কোনো ফি নেই। অনুলিপি সরবরাহ করা হলে তথ্য কমিশন নির্ধারিত যুক্তিসংগত অনুলিপি খরচ নেওয়া হতে পারে, এবং খরচ হওয়ার আগেই পরিমাণ জানানো হবে।</p>"},{"question":"প্রত্যাখ্যাত হলে বা উত্তর না পেলে?","answer":"<p>প্রত্যাখ্যানের বা সময়সীমা পেরোনোর ৩০ দিনের মধ্যে DBEDC-এর আপিল কর্তৃপক্ষের কাছে আপিল করতে পারেন; ১৫ দিনের মধ্যে আপিল নিষ্পত্তি হয়। তাতেও সন্তুষ্ট না হলে বাংলাদেশ তথ্য কমিশনে অভিযোগ করতে পারেন।</p>"},{"question":"কোন তথ্য দেওয়া না-ও হতে পারে?","answer":"<p>কেবল আইনে অব্যাহতিপ্রাপ্ত তথ্য, যেমন প্রকাশ করলে তৃতীয় পক্ষের প্রতিযোগিতামূলক অবস্থান ক্ষতিগ্রস্ত হবে এমন বাণিজ্যিক গোপন তথ্য, ব্যক্তিগত তথ্য, অথবা নিরাপত্তা বা তদন্তে প্রভাব ফেলবে এমন তথ্য। বাকি সব তথ্য প্রকাশযোগ্য।</p>"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"提出申请","intro":"","items":[{"question":"如何申请信息？","answer":"<p>通过<a href=\\"contact\\">联系表单</a>选择“信息申请”主题，或以书面形式向DBEDC指定信息官提出。请提供姓名和地址，尽量准确描述所需信息，并说明获取方式（复印件、电子邮件或查阅）。可使用信息委员会规定的申请表，但并非必需。</p>"},{"question":"多久答复？","answer":"<p>法律规定自收到申请之日起最长20个工作日；涉及第三方的为30个工作日；涉及人身生命或自由的为24小时。无法满足申请的，将书面说明理由。</p>"},{"question":"是否收费？","answer":"<p>提出申请不收费。以复印件形式提供信息的，可能按信息委员会规定收取合理复印费用，并会事先告知金额。</p>"},{"question":"被拒绝或未获答复怎么办？","answer":"<p>可在被拒绝或期限届满后30日内向DBEDC申诉机构提出申诉，申诉在15日内作出决定。仍不满意的，可向孟加拉国信息委员会投诉。</p>"},{"question":"哪些信息可以不公开？","answer":"<p>仅限法律豁免的信息，例如公开后会损害第三方竞争地位的商业秘密、个人信息，或影响安全或调查的信息。其他信息均可公开。</p>"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
