INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Our services and standards","intro":"Every written request made through this website receives a tracking number, and the date by which you will get an answer is shown when you submit it.","items":[{"meta":"At the plaza","title":"Paying a toll","body":"The published rate for your vehicle class, a receipt for every payment, and no charge beyond the published rate."},{"meta":"On the road","title":"Breakdowns and emergencies","body":"Patrol response on the open section at any hour; recovery of a broken-down vehicle to the nearest safe exit."},{"meta":"In writing","title":"Complaints","body":"An acknowledgement with a tracking number at once, and an answer within the published response time."},{"meta":"In writing","title":"Toll disputes","body":"A review of the charge against the plaza record, and a refund of any overcharge."},{"meta":"In writing","title":"Lost property","body":"Items found on the expressway are logged and held; you are contacted if a match is found."},{"meta":"In writing","title":"Information requests","body":"A reply within the time the Right to Information Act 2009 allows."}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"আমাদের সেবা ও মান","intro":"এই ওয়েবসাইটের মাধ্যমে করা প্রতিটি লিখিত অনুরোধ একটি ট্র্যাকিং নম্বর পায়, এবং জমা দেওয়ার সময়ই কোন তারিখের মধ্যে উত্তর পাবেন তা দেখানো হয়।","items":[{"meta":"প্লাজায়","title":"টোল পরিশোধ","body":"আপনার যানবাহন শ্রেণির প্রকাশিত হার, প্রতিটি পরিশোধের রসিদ এবং প্রকাশিত হারের বেশি কোনো অর্থ নয়।"},{"meta":"সড়কে","title":"বিকল যানবাহন ও জরুরি অবস্থা","body":"খোলা অংশে যেকোনো সময় টহল দলের সাড়া; বিকল যানবাহন নিকটতম নিরাপদ প্রস্থানে সরিয়ে নেওয়া।"},{"meta":"লিখিতভাবে","title":"অভিযোগ","body":"সঙ্গে সঙ্গে ট্র্যাকিং নম্বরসহ প্রাপ্তিস্বীকার এবং প্রকাশিত সময়ের মধ্যে উত্তর।"},{"meta":"লিখিতভাবে","title":"টোল বিরোধ","body":"প্লাজার রেকর্ডের সঙ্গে মিলিয়ে চার্জ পর্যালোচনা এবং বেশি নেওয়া অর্থ ফেরত।"},{"meta":"লিখিতভাবে","title":"হারানো জিনিস","body":"এক্সপ্রেসওয়েতে পাওয়া জিনিস লিপিবদ্ধ করে সংরক্ষণ করা হয়; মিল পাওয়া গেলে আপনার সঙ্গে যোগাযোগ করা হয়।"},{"meta":"লিখিতভাবে","title":"তথ্যের অনুরোধ","body":"তথ্য অধিকার আইন ২০০৯-এ নির্ধারিত সময়ের মধ্যে উত্তর।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"服务与标准","intro":"通过本网站提交的每项书面请求都会获得跟踪编号，提交时即显示答复截止日期。","items":[{"meta":"收费站","title":"缴纳通行费","body":"按公布的车型标准收费，每笔付款提供票据，不收取超出公布标准的费用。"},{"meta":"道路上","title":"故障与紧急情况","body":"已通车路段全天候巡逻响应；将故障车辆拖至最近的安全出口。"},{"meta":"书面","title":"投诉","body":"立即确认并提供跟踪编号，在公布的时限内答复。"},{"meta":"书面","title":"收费争议","body":"对照收费站记录复核收费，多收部分予以退还。"},{"meta":"书面","title":"失物招领","body":"在快速路上拾获的物品登记保管，找到匹配物品时与您联系。"},{"meta":"书面","title":"信息公开申请","body":"在《2009年信息权法》规定的时限内答复。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"If we do not meet a standard","body":"<p>Use the <a href=\\"grievances\\">grievance form</a> and quote your tracking number if you have one. If the answer does not resolve the matter, ask for it to be reviewed by the appeal officer named in the reply. You may also use the Government''s Grievance Redress System at <a href=\\"https://www.grs.gov.bd\\">grs.gov.bd</a>.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"মান পূরণ না হলে","body":"<p><a href=\\"grievances\\">অভিযোগ ফরম</a> ব্যবহার করুন এবং ট্র্যাকিং নম্বর থাকলে তা উল্লেখ করুন। উত্তরে সমস্যার সমাধান না হলে উত্তরে নাম দেওয়া আপিল কর্মকর্তার কাছে পুনর্বিবেচনার অনুরোধ করুন। সরকারের অভিযোগ প্রতিকার ব্যবস্থাও ব্যবহার করতে পারেন: <a href=\\"https://www.grs.gov.bd\\">grs.gov.bd</a>।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"未达到标准时","body":"<p>请使用<a href=\\"grievances\\">投诉表单</a>，如有跟踪编号请注明。若答复未能解决问题，可请求答复中指定的申诉官员复核。您也可以使用政府投诉处理系统：<a href=\\"https://www.grs.gov.bd\\">grs.gov.bd</a>。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
