INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Annual reports and audited accounts","body":"<p>DBEDC''s annual report and its financial statements, audited by an independent firm of chartered accountants, are published here after they are approved at the company''s annual general meeting. Monthly traffic counts at the toll plazas are published with the traffic figures above once they have been reviewed.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"বার্ষিক প্রতিবেদন ও নিরীক্ষিত হিসাব","body":"<p>DBEDC-এর বার্ষিক প্রতিবেদন এবং স্বাধীন চার্টার্ড অ্যাকাউন্ট্যান্ট প্রতিষ্ঠান কর্তৃক নিরীক্ষিত আর্থিক বিবরণী কোম্পানির বার্ষিক সাধারণ সভায় অনুমোদনের পর এখানে প্রকাশ করা হয়। টোল প্লাজার মাসিক যানবাহন গণনা পর্যালোচনার পর উপরের যান চলাচলের তথ্যের সঙ্গে প্রকাশ করা হয়।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"年度报告与经审计的财务报表","body":"<p>DBEDC年度报告及经独立特许会计师事务所审计的财务报表，在公司股东年会批准后于此公布。收费站月度车流量数据经审核后与上方交通数据一并公布。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
