INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Policy library","intro":"","documents":[{"title":"Integrity and anti-corruption","description":"Commitments under the National Integrity Strategy and how to report a concern.","file":"about/integrity","fileType":"","fileSize":"","date":""},{"title":"Grievance redress","description":"How complaints are received, answered and escalated.","file":"grievances","fileType":"","fileSize":"","date":""},{"title":"Citizen charter","description":"Service standards for road users.","file":"disclosures/citizen-charter","fileType":"","fileSize":"","date":""},{"title":"Right to information","description":"How to request information and appeal.","file":"disclosures/right-to-information","fileType":"","fileSize":"","date":""},{"title":"Environmental and social safeguards","description":"How the corridor''s environmental and social impacts are managed.","file":"disclosures/environment","fileType":"","fileSize":"","date":""},{"title":"Procurement","description":"How DBEDC buys goods, works and services.","file":"procurement","fileType":"","fileSize":"","date":""},{"title":"Privacy","description":"How personal information is handled on this website.","file":"privacy","fileType":"","fileSize":"","date":""},{"title":"Accessibility","description":"The accessibility standard this website meets and its known gaps.","file":"accessibility","fileType":"","fileSize":"","date":""},{"title":"Rules of the road","description":"Speed limits, prohibited vehicles and conduct on the expressway.","file":"travel/rules","fileType":"","fileSize":"","date":""}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"নীতিমালা সংগ্রহ","intro":"","documents":[{"title":"শুদ্ধাচার ও দুর্নীতিবিরোধী","description":"জাতীয় শুদ্ধাচার কৌশলের আওতায় অঙ্গীকার এবং উদ্বেগ জানানোর পদ্ধতি।","file":"about/integrity","fileType":"","fileSize":"","date":""},{"title":"অভিযোগ প্রতিকার","description":"অভিযোগ কীভাবে গ্রহণ, উত্তর ও ঊর্ধ্বতন পর্যায়ে পাঠানো হয়।","file":"grievances","fileType":"","fileSize":"","date":""},{"title":"নাগরিক সনদ","description":"সড়ক ব্যবহারকারীদের জন্য সেবার মান।","file":"disclosures/citizen-charter","fileType":"","fileSize":"","date":""},{"title":"তথ্য অধিকার","description":"তথ্য চাওয়া ও আপিলের পদ্ধতি।","file":"disclosures/right-to-information","fileType":"","fileSize":"","date":""},{"title":"পরিবেশগত ও সামাজিক সুরক্ষা","description":"করিডোরের পরিবেশগত ও সামাজিক প্রভাব কীভাবে ব্যবস্থাপনা করা হয়।","file":"disclosures/environment","fileType":"","fileSize":"","date":""},{"title":"ক্রয়","description":"DBEDC কীভাবে পণ্য, কাজ ও সেবা ক্রয় করে।","file":"procurement","fileType":"","fileSize":"","date":""},{"title":"গোপনীয়তা","description":"এই ওয়েবসাইটে ব্যক্তিগত তথ্য কীভাবে ব্যবস্থাপনা করা হয়।","file":"privacy","fileType":"","fileSize":"","date":""},{"title":"প্রবেশগম্যতা","description":"এই ওয়েবসাইট যে প্রবেশগম্যতার মান পূরণ করে এবং জানা ঘাটতি।","file":"accessibility","fileType":"","fileSize":"","date":""},{"title":"সড়কের নিয়ম","description":"গতিসীমা, নিষিদ্ধ যানবাহন ও এক্সপ্রেসওয়েতে আচরণ।","file":"travel/rules","fileType":"","fileSize":"","date":""}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"政策汇总","intro":"","documents":[{"title":"廉洁与反腐败","description":"依据国家廉洁战略作出的承诺及举报方式。","file":"about/integrity","fileType":"","fileSize":"","date":""},{"title":"投诉处理","description":"投诉的受理、答复和升级处理方式。","file":"grievances","fileType":"","fileSize":"","date":""},{"title":"公民宪章","description":"面向道路使用者的服务标准。","file":"disclosures/citizen-charter","fileType":"","fileSize":"","date":""},{"title":"信息公开","description":"信息申请及申诉方式。","file":"disclosures/right-to-information","fileType":"","fileSize":"","date":""},{"title":"环境与社会保障","description":"走廊环境和社会影响的管理方式。","file":"disclosures/environment","fileType":"","fileSize":"","date":""},{"title":"采购","description":"DBEDC如何采购货物、工程和服务。","file":"procurement","fileType":"","fileSize":"","date":""},{"title":"隐私","description":"本网站如何处理个人信息。","file":"privacy","fileType":"","fileSize":"","date":""},{"title":"无障碍","description":"本网站达到的无障碍标准及已知不足。","file":"accessibility","fileType":"","fileSize":"","date":""},{"title":"道路规则","description":"限速、禁行车辆及快速路行驶规范。","file":"travel/rules","fileType":"","fileSize":"","date":""}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
