INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'bn', 'পরিবেশগত ও সামাজিক সুরক্ষা', 'ঢাকা বাইপাস এক্সপ্রেসওয়ের পরিবেশগত ও সামাজিক প্রভাব কীভাবে মূল্যায়ন, ব্যবস্থাপনা ও পর্যবেক্ষণ করা হয়।', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'zh', '环境与社会保障', '达卡绕城高速公路环境和社会影响的评估、管理和监测。', 'published');
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'page-header', 0, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"eyebrow":"Disclosures","heading":"Environmental and social safeguards","lede":"A road through farmland, rivers and growing towns changes the places it passes. This is how those changes are managed."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"তথ্য প্রকাশ","heading":"পরিবেশগত ও সামাজিক সুরক্ষা","lede":"কৃষিজমি, নদী ও বেড়ে ওঠা শহরের মধ্য দিয়ে যাওয়া একটি সড়ক আশপাশের এলাকা বদলে দেয়। সেই পরিবর্তন কীভাবে ব্যবস্থাপনা করা হয়, তা এখানে।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"信息公开","heading":"环境与社会保障","lede":"一条穿越农田、河流和发展中城镇的道路会改变沿线地区。以下说明如何管理这些变化。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 1, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"The legal framework","body":"<p>Road projects of this size are classed as “Red” under the Environment Conservation Rules 2023 made under the Bangladesh Environment Conservation Act 1995. They require an environmental impact assessment and an environmental management plan approved by the Department of Environment, and an environmental clearance certificate that is renewed during construction and operation. Land for the project is acquired by the Government under the Acquisition and Requisition of Immovable Property Act 2017; see <a href=\\"disclosures/land-acquisition\\">land acquisition</a>.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"আইনি কাঠামো","body":"<p>বাংলাদেশ পরিবেশ সংরক্ষণ আইন ১৯৯৫-এর অধীনে প্রণীত পরিবেশ সংরক্ষণ বিধিমালা ২০২৩ অনুযায়ী এই আকারের সড়ক প্রকল্প “লাল” শ্রেণিভুক্ত। এর জন্য পরিবেশ অধিদপ্তর কর্তৃক অনুমোদিত পরিবেশগত প্রভাব নিরূপণ ও পরিবেশ ব্যবস্থাপনা পরিকল্পনা এবং নির্মাণ ও পরিচালনাকালে নবায়নযোগ্য পরিবেশ ছাড়পত্র প্রয়োজন। প্রকল্পের ভূমি স্থাবর সম্পত্তি অধিগ্রহণ ও হুকুমদখল আইন ২০১৭-এর অধীনে সরকার অধিগ্রহণ করে; দেখুন <a href=\\"disclosures/land-acquisition\\">ভূমি অধিগ্রহণ</a>।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"法律框架","body":"<p>根据《1995年孟加拉国环境保护法》制定的《2023年环境保护规则》，此类规模的道路项目属于“红色”类别，须编制经环境局批准的环境影响评价和环境管理计划，并取得在建设和运营期间定期更新的环境许可证。项目用地由政府依据《2017年不动产征收征用法》征收，详见<a href=\\"disclosures/land-acquisition\\">征地</a>。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'card-grid', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"What is managed, and how","intro":"","items":[{"meta":"Air","title":"Dust and emissions","body":"Watering of haul roads and stockpiles, covered transport of loose material, and maintained plant."},{"meta":"Water","title":"Rivers, canals and drainage","body":"Cross-drainage culverts and bridges sized to keep floodwater moving, and no discharge of construction waste into watercourses."},{"meta":"Noise","title":"Communities near the road","body":"Limits on night work near homes and schools, and monitoring at sensitive locations."},{"meta":"Nature","title":"Trees and green cover","body":"Compensatory planting along the corridor for trees removed during construction."},{"meta":"People","title":"Safety and access","body":"Safe crossings and service roads so communities stay connected, and a safety plan for workers and the public."},{"meta":"People","title":"Grievances","body":"Anyone affected by construction or operation can complain through the grievance form and receives a tracking number."}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"কী ব্যবস্থাপনা করা হয় এবং কীভাবে","intro":"","items":[{"meta":"বায়ু","title":"ধুলা ও নির্গমন","body":"পরিবহন পথ ও মজুদে পানি ছিটানো, খোলা সামগ্রী ঢেকে পরিবহন এবং রক্ষণাবেক্ষিত যন্ত্রপাতি।"},{"meta":"পানি","title":"নদী, খাল ও নিষ্কাশন","body":"বন্যার পানি প্রবাহ বজায় রাখতে উপযুক্ত আকারের কালভার্ট ও সেতু, এবং জলাধারে নির্মাণ বর্জ্য না ফেলা।"},{"meta":"শব্দ","title":"সড়কের কাছের জনবসতি","body":"বাড়ি ও বিদ্যালয়ের কাছে রাতের কাজে সীমাবদ্ধতা এবং সংবেদনশীল স্থানে পর্যবেক্ষণ।"},{"meta":"প্রকৃতি","title":"গাছ ও সবুজ আচ্ছাদন","body":"নির্মাণকালে কাটা গাছের পরিবর্তে করিডোর বরাবর ক্ষতিপূরণমূলক বৃক্ষরোপণ।"},{"meta":"মানুষ","title":"নিরাপত্তা ও চলাচল","body":"জনবসতি যাতে সংযুক্ত থাকে সে জন্য নিরাপদ পারাপার ও সার্ভিস রোড, এবং কর্মী ও জনসাধারণের জন্য নিরাপত্তা পরিকল্পনা।"},{"meta":"মানুষ","title":"অভিযোগ","body":"নির্মাণ বা পরিচালনায় ক্ষতিগ্রস্ত যে কেউ অভিযোগ ফরমের মাধ্যমে অভিযোগ করতে পারেন এবং একটি ট্র্যাকিং নম্বর পান।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"管理内容与方式","intro":"","items":[{"meta":"空气","title":"扬尘与排放","body":"对运输道路和堆料洒水，散装材料覆盖运输，机械设备定期维护。"},{"meta":"水","title":"河流、运河与排水","body":"按保持洪水畅通的要求设置涵洞和桥梁，严禁向水体排放施工废弃物。"},{"meta":"噪声","title":"道路附近社区","body":"限制住宅和学校附近夜间施工，并在敏感点开展监测。"},{"meta":"自然","title":"树木与绿化","body":"对施工中移除的树木，沿走廊进行补偿性种植。"},{"meta":"人","title":"安全与通行","body":"设置安全过街设施和辅路，保持社区连通，并制定工人和公众安全计划。"},{"meta":"人","title":"投诉","body":"受施工或运营影响的任何人都可通过投诉表单投诉，并获得跟踪编号。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 3, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Monitoring and documents","body":"<p>Environmental monitoring results are reported to the Department of Environment and the Roads and Highways Department. The environmental clearance, the approved assessment and management plan, and monitoring summaries are listed on this page as they are released for publication.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"পর্যবেক্ষণ ও নথি","body":"<p>পরিবেশ পর্যবেক্ষণের ফলাফল পরিবেশ অধিদপ্তর ও সড়ক ও জনপথ অধিদপ্তরে জমা দেওয়া হয়। পরিবেশ ছাড়পত্র, অনুমোদিত নিরূপণ ও ব্যবস্থাপনা পরিকল্পনা এবং পর্যবেক্ষণের সারসংক্ষেপ প্রকাশের জন্য ছাড় পাওয়ার পর এই পাতায় তালিকাভুক্ত করা হয়।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"监测与文件","body":"<p>环境监测结果报送环境局和孟加拉国公路局。环境许可证、经批准的评价报告和管理计划以及监测摘要，在获准公开后列于本页。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
