INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Taking part","body":"<p>Each notice gives the date, place and subject of the meeting and how to send written comments if you cannot attend. Comments can also be sent at any time through the <a href=\\"contact\\">contact form</a>.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"অংশগ্রহণ","body":"<p>প্রতিটি বিজ্ঞপ্তিতে সভার তারিখ, স্থান ও বিষয় এবং উপস্থিত থাকতে না পারলে লিখিত মতামত পাঠানোর পদ্ধতি দেওয়া থাকে। মতামত যেকোনো সময় <a href=\\"contact\\">যোগাযোগ ফরম</a> দিয়েও পাঠানো যায়।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"如何参与","body":"<p>每份通知均列明会议日期、地点和议题，以及无法出席时提交书面意见的方式。也可随时通过<a href=\\"contact\\">联系表单</a>提交意见。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
