INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Standards applied","intro":"","items":[{"meta":"Design","title":"Roads and Highways Department standards","body":"Geometric design, pavement and structures to RHD''s standards and specifications for national highways, reviewed by RHD for each section."},{"meta":"Structures","title":"Bridge design codes","body":"Bridges and flyovers designed to the loading and design codes adopted by RHD, including provision for heavy freight vehicles."},{"meta":"Traffic","title":"Signs, markings and speed","body":"Road signs and markings to the Bangladesh road sign manual; speed limits under the Motor Vehicle Speed Limit Guideline 2024."},{"meta":"Law","title":"Road Transport Act 2018","body":"The rules of the road, vehicle fitness, loads and penalties that apply on the expressway."},{"meta":"Tolls","title":"Toll Policy","body":"Tolls set by government notification under the national toll policy for bridges and roads."},{"meta":"Safeguards","title":"Environment Conservation Rules 2023","body":"Environmental assessment, management and monitoring; see environmental and social safeguards."}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"প্রযোজ্য মান","intro":"","items":[{"meta":"নকশা","title":"সড়ক ও জনপথ অধিদপ্তরের মান","body":"জাতীয় মহাসড়কের জন্য সওজ-এর মান ও স্পেসিফিকেশন অনুযায়ী জ্যামিতিক নকশা, পেভমেন্ট ও অবকাঠামো; প্রতিটি অংশ সওজ কর্তৃক পর্যালোচিত।"},{"meta":"অবকাঠামো","title":"সেতু নকশা কোড","body":"ভারী পণ্যবাহী যানবাহনের ব্যবস্থাসহ সওজ গৃহীত লোডিং ও নকশা কোড অনুযায়ী সেতু ও ফ্লাইওভার নকশা।"},{"meta":"ট্রাফিক","title":"সাইন, মার্কিং ও গতি","body":"বাংলাদেশ সড়ক সাইন ম্যানুয়াল অনুযায়ী সাইন ও মার্কিং; মোটরযানের গতিসীমা নির্দেশিকা ২০২৪ অনুযায়ী গতিসীমা।"},{"meta":"আইন","title":"সড়ক পরিবহন আইন ২০১৮","body":"এক্সপ্রেসওয়েতে প্রযোজ্য সড়কের নিয়ম, যানবাহনের ফিটনেস, ভার ও দণ্ড।"},{"meta":"টোল","title":"টোল নীতিমালা","body":"সেতু ও সড়কের জাতীয় টোল নীতিমালার আওতায় সরকারি প্রজ্ঞাপনে নির্ধারিত টোল।"},{"meta":"সুরক্ষা","title":"পরিবেশ সংরক্ষণ বিধিমালা ২০২৩","body":"পরিবেশগত নিরূপণ, ব্যবস্থাপনা ও পর্যবেক্ষণ; দেখুন পরিবেশগত ও সামাজিক সুরক্ষা।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"适用标准","intro":"","items":[{"meta":"设计","title":"孟加拉国公路局标准","body":"几何设计、路面和构造物按公路局国道标准与规范执行，每个路段均经公路局审查。"},{"meta":"构造物","title":"桥梁设计规范","body":"桥梁和高架桥按公路局采用的荷载和设计规范设计，并考虑重型货车通行。"},{"meta":"交通","title":"标志、标线与限速","body":"交通标志和标线符合孟加拉国道路标志手册；限速依据《2024年机动车限速指南》。"},{"meta":"法律","title":"《2018年道路运输法》","body":"快速路适用的道路规则、车辆技术状况、载重及处罚规定。"},{"meta":"收费","title":"收费政策","body":"依据国家桥梁和道路收费政策，由政府公告确定通行费。"},{"meta":"保障","title":"《2023年环境保护规则》","body":"环境评价、管理和监测；详见环境与社会保障。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Management systems","body":"<p>DBEDC is working towards certification of its management systems for quality (ISO 9001), environment (ISO 14001), occupational health and safety (ISO 45001) and road traffic safety (ISO 39001). A certificate is listed here only once it has been issued by an accredited certification body.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"ব্যবস্থাপনা পদ্ধতি","body":"<p>DBEDC তার মান (ISO 9001), পরিবেশ (ISO 14001), পেশাগত স্বাস্থ্য ও নিরাপত্তা (ISO 45001) এবং সড়ক ট্রাফিক নিরাপত্তা (ISO 39001) ব্যবস্থাপনা পদ্ধতির সনদ অর্জনের দিকে কাজ করছে। স্বীকৃত সনদ প্রদানকারী প্রতিষ্ঠান সনদ ইস্যু করার পরই কেবল তা এখানে তালিকাভুক্ত হয়।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"管理体系","body":"<p>DBEDC正在推进质量（ISO 9001）、环境（ISO 14001）、职业健康安全（ISO 45001）和道路交通安全（ISO 39001）管理体系认证。证书仅在获认可认证机构颁发后才在此列出。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
