INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"ভ্রমণ তথ্য","heading":"যানবাহনের শ্রেণি","lede":"টোল নির্ভর করে আপনার যানবাহনের শ্রেণির ওপর। শ্রেণি নির্ধারিত হয় নিবন্ধনে লিপিবদ্ধ যানবাহনের ধরন, আকার ও এক্সেল অনুযায়ী।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"出行信息","heading":"车型分类","lede":"通行费取决于车辆类别。类别按行驶证登记的车辆类型、尺寸和轴数确定。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
