INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Which class am I?","intro":"The amount for each class is on the toll rates page; the descriptions below help you find your class.","items":[{"meta":"Light","title":"Cars and SUVs","body":"Private cars, jeeps and sport-utility vehicles, including taxis and ride-hailing cars."},{"meta":"Light","title":"Microbuses and pick-ups","body":"Microbuses, pick-up vans, and light utility vehicles such as wreckers."},{"meta":"Passenger","title":"Minibuses and coasters","body":"Buses with up to 30 seats."},{"meta":"Passenger","title":"Large buses","body":"Buses with 31 or more seats, including double-deckers."},{"meta":"Goods","title":"Small trucks","body":"Two-axle trucks up to about 3 tonnes laden."},{"meta":"Goods","title":"Medium trucks","body":"Two-axle trucks of about 5 to 7 tonnes laden."},{"meta":"Goods","title":"Heavy trucks","body":"Trucks with two or three axles over about 7 tonnes laden."},{"meta":"Goods","title":"Trailers and articulated trucks","body":"Prime movers with trailers, and trucks with more than three axles."}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"আমার শ্রেণি কোনটি?","intro":"প্রতিটি শ্রেণির টোল টোল হার পাতায় আছে; নিচের বর্ণনা আপনার শ্রেণি খুঁজে পেতে সাহায্য করবে।","items":[{"meta":"হালকা","title":"কার ও এসইউভি","body":"ব্যক্তিগত গাড়ি, জিপ ও স্পোর্ট ইউটিলিটি যান, ট্যাক্সি ও রাইড শেয়ারিং গাড়িসহ।"},{"meta":"হালকা","title":"মাইক্রোবাস ও পিকআপ","body":"মাইক্রোবাস, পিকআপ ভ্যান এবং রেকারের মতো হালকা ইউটিলিটি যান।"},{"meta":"যাত্রীবাহী","title":"মিনিবাস ও কোস্টার","body":"৩০ আসন পর্যন্ত বাস।"},{"meta":"যাত্রীবাহী","title":"বড় বাস","body":"৩১ বা তার বেশি আসনের বাস, দোতলা বাসসহ।"},{"meta":"পণ্যবাহী","title":"ছোট ট্রাক","body":"বোঝাই অবস্থায় প্রায় ৩ টন পর্যন্ত দুই এক্সেলের ট্রাক।"},{"meta":"পণ্যবাহী","title":"মাঝারি ট্রাক","body":"বোঝাই অবস্থায় প্রায় ৫ থেকে ৭ টনের দুই এক্সেলের ট্রাক।"},{"meta":"পণ্যবাহী","title":"ভারী ট্রাক","body":"বোঝাই অবস্থায় প্রায় ৭ টনের বেশি দুই বা তিন এক্সেলের ট্রাক।"},{"meta":"পণ্যবাহী","title":"ট্রেইলার ও আর্টিকুলেটেড ট্রাক","body":"ট্রেইলারসহ প্রাইম মুভার এবং তিনের বেশি এক্সেলের ট্রাক।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"我属于哪一类？","intro":"各类别收费金额见通行费标准页面；以下说明帮助您确定所属类别。","items":[{"meta":"轻型","title":"轿车和SUV","body":"私家车、吉普车和运动型多用途车，包括出租车和网约车。"},{"meta":"轻型","title":"面包车和皮卡","body":"面包车、皮卡以及清障车等轻型多用途车辆。"},{"meta":"客车","title":"中巴和考斯特","body":"30座及以下客车。"},{"meta":"客车","title":"大型客车","body":"31座及以上客车，包括双层巴士。"},{"meta":"货车","title":"小型货车","body":"满载约3吨以内的两轴货车。"},{"meta":"货车","title":"中型货车","body":"满载约5至7吨的两轴货车。"},{"meta":"货车","title":"重型货车","body":"满载约7吨以上的两轴或三轴货车。"},{"meta":"货车","title":"拖挂车和铰接式货车","body":"带挂车的牵引车，以及三轴以上货车。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 3, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Edge cases","body":"<ul><li><strong>Covered vans</strong> are classed as trucks by their axles and laden weight, not by their shape.</li><li><strong>A vehicle towing another</strong> pays for each vehicle; a vehicle towed by the patrol after a breakdown does not pay.</li><li><strong>Emergency vehicles on duty</strong> — ambulances and fire service vehicles — pass without charge, as do other vehicles exempted by government notification.</li><li><strong>If you think you were placed in the wrong class</strong>, pay the toll shown, keep the receipt, and raise a <a href=\\"travel/toll-dispute\\">toll dispute</a>.</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"সীমান্তবর্তী ক্ষেত্র","body":"<ul><li><strong>কাভার্ড ভ্যান</strong> আকৃতি নয়, এক্সেল ও বোঝাই ওজন অনুযায়ী ট্রাক হিসেবে শ্রেণিভুক্ত।</li><li><strong>অন্য যানবাহন টেনে নেওয়া যানবাহন</strong> প্রতিটি যানবাহনের জন্য টোল দেয়; বিকল হওয়ার পর টহল দল যে যানবাহন টেনে নেয় তার টোল লাগে না।</li><li><strong>দায়িত্বরত জরুরি যানবাহন</strong> — অ্যাম্বুলেন্স ও ফায়ার সার্ভিসের গাড়ি — বিনা টোলে যায়, সরকারি প্রজ্ঞাপনে অব্যাহতিপ্রাপ্ত অন্যান্য যানবাহনও।</li><li><strong>ভুল শ্রেণিতে ধরা হয়েছে মনে হলে</strong> দেখানো টোল পরিশোধ করুন, রসিদ রাখুন এবং <a href=\\"travel/toll-dispute\\">টোল বিরোধ</a> জানান।</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"特殊情况","body":"<ul><li><strong>厢式货车</strong>按轴数和满载重量归入货车类别，而非按外形。</li><li><strong>拖带其他车辆的</strong>，每辆车分别缴费；故障后由巡逻车拖离的车辆免费。</li><li><strong>执行任务的应急车辆</strong>——救护车和消防车——免费通行，其他经政府公告免征的车辆同样免费。</li><li><strong>如认为车型归类错误</strong>，请先按显示金额缴费并保留票据，然后提出<a href=\\"travel/toll-dispute\\">收费争议</a>。</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
