INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"ভ্রমণ তথ্য","heading":"টোল পরিশোধ","lede":"টোল সড়কে ওঠার বা নামার সময় প্লাজায় টোল পরিশোধ করতে হয়। আপনার যানবাহন শ্রেণির অর্থ প্রস্তুত রাখুন।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
