INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"At the plaza","body":"<ul><li>Slow down and follow the lane signs for your vehicle class.</li><li>Pay the amount shown for your class. The payment methods each plaza accepts are listed with the rates above.</li><li>Take your receipt, and keep it until the end of your journey: it is your proof of payment for a dispute or a claim.</li><li>Never pay anyone who is not at a toll booth, and never pay more than the published rate.</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"প্লাজায়","body":"<ul><li>গতি কমান এবং আপনার যানবাহন শ্রেণির লেন সাইন অনুসরণ করুন।</li><li>আপনার শ্রেণির জন্য দেখানো অর্থ পরিশোধ করুন। প্রতিটি প্লাজায় গৃহীত পরিশোধ পদ্ধতি উপরের হারের সঙ্গে তালিকাভুক্ত।</li><li>রসিদ নিন এবং যাত্রা শেষ হওয়া পর্যন্ত রাখুন: বিরোধ বা দাবির ক্ষেত্রে এটিই পরিশোধের প্রমাণ।</li><li>টোল বুথের বাইরে কাউকে টাকা দেবেন না এবং প্রকাশিত হারের বেশি কখনো দেবেন না।</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"在收费站","body":"<ul><li>减速并按车型车道标志行驶。</li><li>按车型显示金额缴费。各收费站接受的支付方式列于上方费率表。</li><li>索取并保留票据至行程结束：这是发生争议或索赔时的付款凭证。</li><li>切勿向收费亭以外的人付款，切勿支付超过公布标准的费用。</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 4, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Electronic toll collection","body":"<p>Electronic toll collection lets a vehicle with a registered tag pass a dedicated lane without stopping, with the toll deducted from a prepaid account. It will follow the national electronic toll collection scheme used on other Bangladesh expressways and bridges, so that one tag works across them. When it is introduced on this expressway, the lanes, how to get a tag and how to top up will be published on this page, and the payment methods shown with the rates will change the same day.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"ইলেকট্রনিক টোল আদায়","body":"<p>ইলেকট্রনিক টোল আদায় পদ্ধতিতে নিবন্ধিত ট্যাগযুক্ত যানবাহন না থেমে নির্দিষ্ট লেন দিয়ে যেতে পারে এবং প্রিপেইড হিসাব থেকে টোল কেটে নেওয়া হয়। এটি বাংলাদেশের অন্যান্য এক্সপ্রেসওয়ে ও সেতুতে ব্যবহৃত জাতীয় ইলেকট্রনিক টোল আদায় ব্যবস্থা অনুসরণ করবে, যাতে একটি ট্যাগ সব জায়গায় কাজ করে। এই এক্সপ্রেসওয়েতে চালু হলে লেন, ট্যাগ পাওয়ার ও রিচার্জের পদ্ধতি এই পাতায় প্রকাশিত হবে এবং একই দিনে হারের সঙ্গে দেখানো পরিশোধ পদ্ধতিও হালনাগাদ হবে।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"电子收费","body":"<p>电子收费允许装有注册标签的车辆通过专用车道不停车通行，通行费从预付账户中扣除。本快速路的电子收费将采用孟加拉国其他快速路和桥梁使用的全国电子收费系统，一张标签通用。在本快速路启用后，相关车道、办理标签和充值方式将在本页公布，费率表中的支付方式也将同日更新。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
