INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Rain, flood and fog","body":"<p>The expressway crosses low-lying land and several rivers, and the monsoon and winter fog are the two conditions that most affect it.</p><ul><li><strong>Heavy rain:</strong> slow down well below the limit, increase your following distance, and switch on dipped headlights. Standing water can cause a vehicle to aquaplane.</li><li><strong>Flooding:</strong> never drive into water across the road. Where a section is closed for flooding it is shown above, with the diversion.</li><li><strong>Fog:</strong> use dipped headlights and fog lights, not full beam; do not stop on the carriageway; leave at the next exit if visibility is too poor to continue.</li></ul><p>The Bangladesh Meteorological Department publishes forecasts and weather warnings at <a href=\\"https://live6.bmd.gov.bd\\">bmd.gov.bd</a>.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"বৃষ্টি, বন্যা ও কুয়াশা","body":"<p>এক্সপ্রেসওয়েটি নিচু জমি ও কয়েকটি নদী অতিক্রম করে; বর্ষা ও শীতের কুয়াশা এর ওপর সবচেয়ে বেশি প্রভাব ফেলে।</p><ul><li><strong>ভারী বৃষ্টি:</strong> গতিসীমার অনেক নিচে চালান, সামনের গাড়ি থেকে দূরত্ব বাড়ান এবং লো-বিম হেডলাইট জ্বালান। জমে থাকা পানিতে গাড়ি পিছলে যেতে পারে।</li><li><strong>বন্যা:</strong> সড়কের ওপর দিয়ে বয়ে যাওয়া পানিতে কখনো গাড়ি নামাবেন না। বন্যার কারণে কোনো অংশ বন্ধ থাকলে তা বিকল্প পথসহ উপরে দেখানো হয়।</li><li><strong>কুয়াশা:</strong> হাই-বিম নয়, লো-বিম হেডলাইট ও ফগ লাইট ব্যবহার করুন; ক্যারেজওয়েতে থামবেন না; দৃশ্যমানতা খুব কম হলে পরবর্তী প্রস্থান দিয়ে বেরিয়ে যান।</li></ul><p>বাংলাদেশ আবহাওয়া অধিদপ্তর পূর্বাভাস ও সতর্কবার্তা প্রকাশ করে: <a href=\\"https://live6.bmd.gov.bd\\">bmd.gov.bd</a>।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"雨天、洪水与大雾","body":"<p>快速路穿越低洼地带和多条河流，季风雨季和冬季大雾对其影响最大。</p><ul><li><strong>暴雨：</strong>大幅降低车速，加大跟车距离，开启近光灯。路面积水可能导致车辆打滑。</li><li><strong>洪水：</strong>切勿驶入漫过路面的积水。因洪水封闭的路段及绕行路线见上方。</li><li><strong>大雾：</strong>使用近光灯和雾灯，勿用远光灯；不要在车道上停车；能见度过低时从下一个出口驶离。</li></ul><p>孟加拉国气象局发布天气预报和预警：<a href=\\"https://live6.bmd.gov.bd\\">bmd.gov.bd</a>。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
