INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"eyebrow":"Travel information","heading":"Freight and heavy vehicles","lede":"The expressway exists to move freight between the industrial north and the southern ports without crossing Dhaka. These are the rules for goods vehicles."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"ভ্রমণ তথ্য","heading":"পণ্য পরিবহন ও ভারী যানবাহন","lede":"ঢাকা পার না হয়ে উত্তরের শিল্পাঞ্চল ও দক্ষিণের বন্দরের মধ্যে পণ্য পরিবহনের জন্যই এক্সপ্রেসওয়েটি। পণ্যবাহী যানবাহনের নিয়ম এখানে।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"出行信息","heading":"货运与重型车辆","lede":"快速路的建设目的，是让货物在北部工业区与南部港口之间运输时无需穿越达卡。以下为货车通行规则。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'card-grid', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Rules for goods vehicles","intro":"","items":[{"meta":"Loads","title":"Axle load limits","body":"Goods vehicles must stay within the legal axle load limits enforced by the Roads and Highways Department under its axle load control policy and the Road Transport Act 2018. Overloading destroys pavement and bridges."},{"meta":"Loads","title":"Weighbridges","body":"Vehicles may be directed to a weighbridge. An overloaded vehicle can be refused entry, required to unload the excess, and fined."},{"meta":"Size","title":"Oversize and abnormal loads","body":"Loads wider, longer or taller than the legal dimensions need a movement permit from the Roads and Highways Department before travel, and may be escorted or limited to set hours."},{"meta":"Lanes","title":"Keep left","body":"Heavy vehicles use the left lane except to overtake, and must not overtake on bridges or at interchanges."},{"meta":"Safety","title":"Secure the load","body":"Loads must be covered and secured. Loose material falling on the carriageway is a danger to every vehicle behind."},{"meta":"Tolls","title":"Classes for goods vehicles","body":"Goods vehicles pay by class, from small trucks to trailers; see vehicle classes and the fare between any two plazas."}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"পণ্যবাহী যানবাহনের নিয়ম","intro":"","items":[{"meta":"ভার","title":"এক্সেল লোড সীমা","body":"সড়ক ও জনপথ অধিদপ্তরের এক্সেল লোড নিয়ন্ত্রণ নীতিমালা ও সড়ক পরিবহন আইন ২০১৮ অনুযায়ী প্রয়োগকৃত আইনি এক্সেল লোড সীমার মধ্যে পণ্যবাহী যানবাহন চলতে হবে। অতিরিক্ত ভার পেভমেন্ট ও সেতু নষ্ট করে।"},{"meta":"ভার","title":"ওজন স্কেল","body":"যানবাহনকে ওজন স্কেলে পাঠানো হতে পারে। অতিরিক্ত ভারবাহী যানবাহনকে প্রবেশে বাধা, অতিরিক্ত মাল নামাতে বাধ্য এবং জরিমানা করা যেতে পারে।"},{"meta":"আকার","title":"অতিরিক্ত আকারের ও অস্বাভাবিক মাল","body":"আইনি মাপের চেয়ে চওড়া, লম্বা বা উঁচু মাল পরিবহনের আগে সড়ক ও জনপথ অধিদপ্তরের চলাচল অনুমতি প্রয়োজন; এসকর্ট বা নির্দিষ্ট সময়ে সীমাবদ্ধ করা হতে পারে।"},{"meta":"লেন","title":"বাম দিকে থাকুন","body":"ভারী যানবাহন ওভারটেক ছাড়া বাম লেন ব্যবহার করবে এবং সেতু বা ইন্টারচেঞ্জে ওভারটেক করবে না।"},{"meta":"নিরাপত্তা","title":"মাল সুরক্ষিত রাখুন","body":"মাল ঢেকে ও সুরক্ষিতভাবে বাঁধতে হবে। ক্যারেজওয়েতে পড়া খোলা মাল পেছনের প্রতিটি যানবাহনের জন্য বিপজ্জনক।"},{"meta":"টোল","title":"পণ্যবাহী যানবাহনের শ্রেণি","body":"ছোট ট্রাক থেকে ট্রেইলার পর্যন্ত পণ্যবাহী যানবাহন শ্রেণি অনুযায়ী টোল দেয়; দেখুন যানবাহনের শ্রেণি এবং যেকোনো দুই প্লাজার মধ্যকার ভাড়া।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"货车规则","intro":"","items":[{"meta":"载重","title":"轴载限值","body":"货车须遵守公路局轴载控制政策及《2018年道路运输法》规定的法定轴载限值。超载会严重损坏路面和桥梁。"},{"meta":"载重","title":"称重站","body":"车辆可能被引导至称重站。超载车辆可能被拒绝驶入、责令卸载超出部分并处以罚款。"},{"meta":"尺寸","title":"超限及大件运输","body":"宽度、长度或高度超过法定尺寸的货物，须事先取得公路局通行许可，并可能需要护送或限定通行时段。"},{"meta":"车道","title":"靠左行驶","body":"重型车辆除超车外须使用左侧车道，不得在桥梁或互通立交处超车。"},{"meta":"安全","title":"固定货物","body":"货物须覆盖并固定。散落在车道上的物料会危及后方所有车辆。"},{"meta":"收费","title":"货车类别","body":"货车按类别缴费，从小型货车到拖挂车；详见车型分类及任意两个收费站之间的费用。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
