INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"If you break down","body":"<ol><li>Move as far left as you can onto the hard shoulder, switch on your hazard lights and place the warning triangle well behind the vehicle.</li><li>Get everyone out on the side away from traffic and stand behind the barrier. Never walk on the carriageway.</li><li>Call the emergency number above. Tell the operator the kilometre marker, your direction and your vehicle.</li><li>Wait for the patrol. Recovery to the nearest safe exit is arranged by DBEDC; onward towing is at the owner''s cost.</li></ol>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"গাড়ি বিকল হলে","body":"<ol><li>যতটা সম্ভব বাম দিকে হার্ড শোল্ডারে সরে যান, হ্যাজার্ড লাইট জ্বালান এবং গাড়ির অনেক পেছনে সতর্কীকরণ ত্রিভুজ রাখুন।</li><li>সবাইকে যানবাহনের উল্টো দিক দিয়ে নামিয়ে ব্যারিয়ারের পেছনে দাঁড়ান। কখনো ক্যারেজওয়েতে হাঁটবেন না।</li><li>উপরের জরুরি নম্বরে কল করুন। কিলোমিটার ফলক, আপনার দিক ও যানবাহনের তথ্য জানান।</li><li>টহল দলের জন্য অপেক্ষা করুন। নিকটতম নিরাপদ প্রস্থান পর্যন্ত উদ্ধারের ব্যবস্থা DBEDC করে; এরপর টোয়িংয়ের খরচ মালিকের।</li></ol>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"车辆故障时","body":"<ol><li>尽量靠左驶入硬路肩，打开危险警示灯，并在车后足够远处放置警示三角牌。</li><li>所有人从远离车流一侧下车，站到护栏后方。切勿在车道上行走。</li><li>拨打上方紧急电话，告知公里桩号、行驶方向和车辆信息。</li><li>等待巡逻车。DBEDC负责将车辆拖至最近的安全出口；后续拖车费用由车主承担。</li></ol>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
