INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"eyebrow":"Travel information","heading":"Toll disputes","lede":"If you were charged the wrong amount, placed in the wrong class, or charged twice, tell us. Pay the toll shown at the plaza first, and keep the receipt."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"ভ্রমণ তথ্য","heading":"টোল বিরোধ","lede":"ভুল পরিমাণ নেওয়া হলে, ভুল শ্রেণিতে ধরা হলে বা দুবার নেওয়া হলে জানান। আগে প্লাজায় দেখানো টোল পরিশোধ করুন এবং রসিদ রাখুন।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"出行信息","heading":"收费争议","lede":"如被收取错误金额、归入错误车型或重复收费，请告诉我们。请先按收费站显示金额缴费并保留票据。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"How a dispute is reviewed","body":"<ol><li>The charge is checked against the plaza''s transaction record and camera record for the time on your receipt.</li><li>Your vehicle''s class is checked against its registration.</li><li>If you were overcharged, the difference is refunded and you are told how it will be paid.</li><li>If the charge was correct, the reply explains why. You may ask for the decision to be reviewed through the <a href=\\"grievances\\">grievance process</a>.</li></ol>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"বিরোধ কীভাবে পর্যালোচনা করা হয়","body":"<ol><li>আপনার রসিদের সময় অনুযায়ী প্লাজার লেনদেন রেকর্ড ও ক্যামেরা রেকর্ডের সঙ্গে চার্জ মিলিয়ে দেখা হয়।</li><li>নিবন্ধন অনুযায়ী আপনার যানবাহনের শ্রেণি যাচাই করা হয়।</li><li>বেশি নেওয়া হলে পার্থক্য ফেরত দেওয়া হয় এবং কীভাবে দেওয়া হবে তা জানানো হয়।</li><li>চার্জ সঠিক হলে উত্তরে কারণ ব্যাখ্যা করা হয়। <a href=\\"grievances\\">অভিযোগ প্রক্রিয়ার</a> মাধ্যমে সিদ্ধান্ত পুনর্বিবেচনার অনুরোধ করতে পারেন।</li></ol>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"争议复核流程","body":"<ol><li>按票据时间核对收费站交易记录和监控录像。</li><li>对照行驶证核实车辆类别。</li><li>如确属多收，退还差额并告知退款方式。</li><li>如收费无误，答复中说明理由。您可通过<a href=\\"grievances\\">投诉程序</a>申请复核。</li></ol>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
