INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"kind":"toll_dispute","slaDays":0,"heading":"Raise a toll dispute","intro":"Give the plaza, the date and time on your receipt, your vehicle number and what went wrong.","successNote":"Keep your receipt until the dispute is closed."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"kind":"toll_dispute","slaDays":0,"heading":"টোল বিরোধ জানান","intro":"প্লাজা, রসিদে থাকা তারিখ ও সময়, যানবাহনের নম্বর এবং কী ভুল হয়েছে তা জানান।","successNote":"বিরোধ নিষ্পত্তি না হওয়া পর্যন্ত রসিদ রাখুন।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"kind":"toll_dispute","slaDays":0,"heading":"提出收费争议","intro":"请提供收费站、票据上的日期和时间、车牌号以及问题描述。","successNote":"争议处理完毕前请保留票据。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
