INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"","intro":"","showFilter":"yes","items":[{"question":"Which parts of the expressway are open?","answer":"<p>The sections open to traffic, and those still under construction, are shown on <a href=\\"travel/status\\">what''s open</a>, which is updated as sections open.</p>"},{"question":"How much is the toll?","answer":"<p>It depends on your vehicle class and where you join and leave. See <a href=\\"travel/toll\\">toll rates</a> and the fare calculator on that page.</p>"},{"question":"Can motorcycles and CNG auto-rickshaws use the expressway?","answer":"<p>No. Motorcycles, three-wheelers and non-motorised vehicles are not allowed on the toll carriageways. See <a href=\\"travel/rules\\">rules of the road</a>.</p>"},{"question":"What is the speed limit?","answer":"<p>80 km/h for cars, buses and microbuses and 50 km/h for trucks on the toll carriageways, unless signs show a lower limit. See <a href=\\"travel/rules\\">rules of the road</a>.</p>"},{"question":"How do I pay?","answer":"<p>At the toll plaza when you join or leave the toll carriageway. See <a href=\\"travel/payment\\">paying the toll</a>.</p>"},{"question":"I think I was charged the wrong toll. What can I do?","answer":"<p>Keep your receipt and raise a <a href=\\"travel/toll-dispute\\">toll dispute</a>. Any overcharge is refunded.</p>"},{"question":"My vehicle broke down. Who do I call?","answer":"<p>The emergency number at the foot of every page. See <a href=\\"travel/breakdown\\">breakdown assistance</a> for what to do while you wait.</p>"},{"question":"I lost something on the expressway.","answer":"<p>Report it on <a href=\\"travel/lost-found\\">lost and found</a>.</p>"},{"question":"Is any part of the road closed today?","answer":"<p>Current and planned closures are listed on <a href=\\"travel/advisories\\">closures and advisories</a>, and the most serious one appears at the top of every page.</p>"},{"question":"How do I complain?","answer":"<p>Through the <a href=\\"grievances\\">grievance form</a>. You get a tracking number and an answer within the published response time.</p>"},{"question":"Who owns the expressway?","answer":"<p>The Government of Bangladesh. DBEDC builds, finances, operates and maintains it under a 25-year concession and then hands it back. See <a href=\\"about/concession\\">concession and financing</a>.</p>"},{"question":"How can I get information that is not on the website?","answer":"<p>Make a request under the Right to Information Act 2009. See <a href=\\"disclosures/right-to-information\\">right to information</a>.</p>"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"","intro":"","showFilter":"yes","items":[{"question":"এক্সপ্রেসওয়ের কোন অংশ খোলা?","answer":"<p>যান চলাচলের জন্য খোলা এবং নির্মাণাধীন অংশগুলো <a href=\\"travel/status\\">কী খোলা আছে</a> পাতায় দেখানো হয়, যা অংশ খোলার সঙ্গে সঙ্গে হালনাগাদ হয়।</p>"},{"question":"টোল কত?","answer":"<p>আপনার যানবাহনের শ্রেণি এবং কোথায় উঠবেন ও নামবেন তার ওপর নির্ভর করে। দেখুন <a href=\\"travel/toll\\">টোল হার</a> ও সেই পাতার ভাড়া হিসাবকারী।</p>"},{"question":"মোটরসাইকেল ও সিএনজি অটোরিকশা কি এক্সপ্রেসওয়ে ব্যবহার করতে পারে?","answer":"<p>না। টোল সড়কে মোটরসাইকেল, থ্রি-হুইলার ও অযান্ত্রিক যানবাহন অনুমোদিত নয়। দেখুন <a href=\\"travel/rules\\">সড়ক বিধি</a>।</p>"},{"question":"গতিসীমা কত?","answer":"<p>টোল সড়কে কার, বাস ও মাইক্রোবাসের জন্য ঘণ্টায় ৮০ কিমি এবং ট্রাকের জন্য ঘণ্টায় ৫০ কিমি, সাইনে কম সীমা দেখানো না থাকলে। দেখুন <a href=\\"travel/rules\\">সড়ক বিধি</a>।</p>"},{"question":"কীভাবে পরিশোধ করব?","answer":"<p>টোল সড়কে ওঠার বা নামার সময় টোল প্লাজায়। দেখুন <a href=\\"travel/payment\\">টোল পরিশোধ</a>।</p>"},{"question":"মনে হচ্ছে ভুল টোল নেওয়া হয়েছে। কী করব?","answer":"<p>রসিদ রাখুন এবং <a href=\\"travel/toll-dispute\\">টোল বিরোধ</a> জানান। বেশি নেওয়া অর্থ ফেরত দেওয়া হয়।</p>"},{"question":"গাড়ি বিকল হয়েছে। কাকে ফোন করব?","answer":"<p>প্রতিটি পাতার নিচে দেওয়া জরুরি নম্বরে। অপেক্ষার সময় কী করবেন তা <a href=\\"travel/breakdown\\">বিকল যানবাহনে সহায়তা</a> পাতায় দেখুন।</p>"},{"question":"এক্সপ্রেসওয়েতে কিছু হারিয়েছি।","answer":"<p><a href=\\"travel/lost-found\\">হারানো ও প্রাপ্তি</a> পাতায় জানান।</p>"},{"question":"আজ সড়কের কোনো অংশ বন্ধ কি?","answer":"<p>চলমান ও পরিকল্পিত সড়ক বন্ধ <a href=\\"travel/advisories\\">সড়ক বন্ধ ও বিজ্ঞপ্তি</a> পাতায় তালিকাভুক্ত, এবং সবচেয়ে গুরুতরটি প্রতিটি পাতার ওপরে দেখানো হয়।</p>"},{"question":"কীভাবে অভিযোগ করব?","answer":"<p><a href=\\"grievances\\">অভিযোগ ফরমের</a> মাধ্যমে। আপনি একটি ট্র্যাকিং নম্বর এবং প্রকাশিত সময়ের মধ্যে উত্তর পাবেন।</p>"},{"question":"এক্সপ্রেসওয়ের মালিক কে?","answer":"<p>বাংলাদেশ সরকার। DBEDC ২৫ বছরের কনসেশনের আওতায় এটি নির্মাণ, অর্থায়ন, পরিচালনা ও রক্ষণাবেক্ষণ করে এবং পরে ফেরত দেয়। দেখুন <a href=\\"about/concession\\">কনসেশন ও অর্থায়ন</a>।</p>"},{"question":"ওয়েবসাইটে নেই এমন তথ্য কীভাবে পাব?","answer":"<p>তথ্য অধিকার আইন ২০০৯-এর অধীনে অনুরোধ করুন। দেখুন <a href=\\"disclosures/right-to-information\\">তথ্য অধিকার</a>।</p>"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"","intro":"","showFilter":"yes","items":[{"question":"快速路哪些路段已通车？","answer":"<p>已通车和在建路段见<a href=\\"travel/status\\">通车路段</a>页面，随路段通车及时更新。</p>"},{"question":"通行费是多少？","answer":"<p>取决于车型以及驶入和驶出的位置。详见<a href=\\"travel/toll\\">通行费标准</a>及该页面的费用计算器。</p>"},{"question":"摩托车和CNG三轮车可以使用快速路吗？","answer":"<p>不可以。收费车道禁止摩托车、三轮车和非机动车通行。详见<a href=\\"travel/rules\\">道路规则</a>。</p>"},{"question":"限速是多少？","answer":"<p>收费车道上轿车、客车和面包车限速80公里/小时，货车50公里/小时，另有标志的除外。详见<a href=\\"travel/rules\\">道路规则</a>。</p>"},{"question":"如何缴费？","answer":"<p>驶入或驶出收费车道时在收费站缴费。详见<a href=\\"travel/payment\\">缴纳通行费</a>。</p>"},{"question":"我认为收费有误，怎么办？","answer":"<p>保留票据并提出<a href=\\"travel/toll-dispute\\">收费争议</a>。多收部分将予退还。</p>"},{"question":"车辆发生故障，该打谁的电话？","answer":"<p>拨打每页底部的紧急电话。等待期间的注意事项见<a href=\\"travel/breakdown\\">故障救援</a>。</p>"},{"question":"我在快速路上丢了东西。","answer":"<p>请在<a href=\\"travel/lost-found\\">失物招领</a>页面报告。</p>"},{"question":"今天有路段封闭吗？","answer":"<p>当前及计划中的封闭见<a href=\\"travel/advisories\\">封闭与通告</a>，最重要的一条会显示在每个页面顶部。</p>"},{"question":"如何投诉？","answer":"<p>通过<a href=\\"grievances\\">投诉表单</a>。您将获得跟踪编号，并在公布的时限内得到答复。</p>"},{"question":"快速路归谁所有？","answer":"<p>归孟加拉国政府所有。DBEDC依据25年特许经营协议负责建设、融资、运营和养护，期满后移交。详见<a href=\\"about/concession\\">特许经营与融资</a>。</p>"},{"question":"如何获取网站上没有的信息？","answer":"<p>依据《2009年信息权法》提出申请。详见<a href=\\"disclosures/right-to-information\\">信息公开</a>。</p>"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'cta-band', 2, 'published' FROM DUAL WHERE @fresh = 1;
