INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"About DBEDC — for publication","body":"<p>Dhaka Bypass Expressway Development Company Limited (DBEDC) is the concession company for the Dhaka Bypass Expressway, an access-controlled toll road around the eastern side of Dhaka between Joydebpur in Gazipur and Madanpur in Narayanganj, linking the N1, N2, N3 and N4 national highways. It is Bangladesh''s first road project delivered as a public–private partnership, under a 25-year design, build, finance, operate, maintain and transfer concession granted by the Roads and Highways Department in December 2018. DBEDC''s shareholders are Sichuan Road &amp; Bridge Group, Shamim Enterprise Ltd and UDC Construction Ltd.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"DBEDC সম্পর্কে — প্রকাশের জন্য","body":"<p>ঢাকা বাইপাস এক্সপ্রেসওয়ে ডেভেলপমেন্ট কোম্পানি লিমিটেড (DBEDC) ঢাকা বাইপাস এক্সপ্রেসওয়ের কনসেশন কোম্পানি। এক্সপ্রেসওয়েটি গাজীপুরের জয়দেবপুর থেকে নারায়ণগঞ্জের মদনপুর পর্যন্ত ঢাকার পূর্ব দিক ঘিরে একটি নিয়ন্ত্রিত-প্রবেশ টোল সড়ক, যা N1, N2, N3 ও N4 জাতীয় মহাসড়ককে যুক্ত করে। এটি বাংলাদেশে সরকারি-বেসরকারি অংশীদারিত্বে বাস্তবায়িত প্রথম সড়ক প্রকল্প, যা ডিসেম্বর ২০১৮-এ সড়ক ও জনপথ অধিদপ্তর প্রদত্ত ২৫ বছরের নকশা, নির্মাণ, অর্থায়ন, পরিচালনা, রক্ষণাবেক্ষণ ও হস্তান্তর কনসেশনের আওতায় চলছে। DBEDC-এর শেয়ারহোল্ডার সিচুয়ান রোড অ্যান্ড ব্রিজ গ্রুপ, শামীম এন্টারপ্রাইজ লিমিটেড ও ইউডিসি কনস্ট্রাকশন লিমিটেড।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"关于DBEDC——供发布","body":"<p>达卡绕城高速公路开发有限公司（DBEDC）是达卡绕城高速公路的特许经营公司。该快速路是一条环绕达卡东侧的封闭式收费公路，北起加济普尔的Joydebpur，南至纳拉扬甘杰的Madanpur，连接N1、N2、N3和N4国道。它是孟加拉国首个以政府与社会资本合作模式实施的公路项目，依据孟加拉国公路局于2018年12月授予的25年设计、建设、融资、运营、维护、移交特许经营权实施。DBEDC的股东为四川路桥集团、Shamim Enterprise Ltd和UDC Construction Ltd。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 3, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Press enquiries","body":"<p>Send enquiries through the <a href=\\"contact\\">contact form</a> with the subject “Media”, giving your publication and deadline. Requests to film or photograph on the expressway need written permission in advance: stopping on the carriageway is prohibited for everyone, including crews.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"প্রেস জিজ্ঞাসা","body":"<p><a href=\\"contact\\">যোগাযোগ ফরমে</a> “মিডিয়া” বিষয় বেছে আপনার প্রতিষ্ঠান ও সময়সীমা উল্লেখ করে জিজ্ঞাসা পাঠান। এক্সপ্রেসওয়েতে ভিডিও বা ছবি ধারণের জন্য আগে লিখিত অনুমতি প্রয়োজন: ক্যারেজওয়েতে থামা সবার জন্য নিষিদ্ধ, ক্রুসহ।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"媒体咨询","body":"<p>请通过<a href=\\"contact\\">联系表单</a>选择“媒体”主题提交咨询，并注明所属媒体和截稿时间。在快速路上拍摄视频或照片须事先取得书面许可：任何人（包括摄制组）均不得在车道上停车。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 4, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Using our logo and photographs","body":"<ul><li>The DBEDC logo may be used to identify DBEDC in news reporting. Do not change its colours or proportions, add effects, or place it on a busy background.</li><li>Do not use the logo in a way that suggests DBEDC endorses a product, service or organisation.</li><li>Photographs from the <a href=\\"gallery\\">gallery</a> may be used in news reporting about the expressway, credited “DBEDC”.</li></ul><p>Logos are on the <a href=\\"downloads\\">downloads</a> page.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"আমাদের লোগো ও ছবি ব্যবহার","body":"<ul><li>সংবাদ প্রতিবেদনে DBEDC-কে চিহ্নিত করতে DBEDC লোগো ব্যবহার করা যাবে। এর রং বা অনুপাত পরিবর্তন, ইফেক্ট যোগ বা ব্যস্ত পটভূমিতে স্থাপন করবেন না।</li><li>DBEDC কোনো পণ্য, সেবা বা প্রতিষ্ঠানকে সমর্থন করে এমন ধারণা দেয় এমনভাবে লোগো ব্যবহার করবেন না।</li><li><a href=\\"gallery\\">গ্যালারির</a> ছবি এক্সপ্রেসওয়ে বিষয়ক সংবাদে “DBEDC” কৃতিত্ব দিয়ে ব্যবহার করা যাবে।</li></ul><p>লোগো <a href=\\"downloads\\">ডাউনলোড</a> পাতায় আছে।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"标识和图片使用","body":"<ul><li>DBEDC标识可在新闻报道中用于指代DBEDC。不得更改其颜色或比例、添加效果或置于杂乱背景上。</li><li>不得以暗示DBEDC为任何产品、服务或机构背书的方式使用标识。</li><li><a href=\\"gallery\\">图片库</a>中的照片可用于有关快速路的新闻报道，署名“DBEDC”。</li></ul><p>标识文件见<a href=\\"downloads\\">下载</a>页面。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
