INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'en', 'Road safety education', 'Safe driving on an expressway: speed, following distance, fatigue, lane discipline and what never to do.', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'bn', 'সড়ক নিরাপত্তা শিক্ষা', 'এক্সপ্রেসওয়েতে নিরাপদে গাড়ি চালানো: গতি, দূরত্ব, ক্লান্তি, লেন শৃঙ্খলা এবং কখনো যা করবেন না।', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'zh', '道路安全教育', '高速公路安全驾驶：车速、跟车距离、疲劳驾驶、车道纪律及绝对禁止的行为。', 'published');
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'page-header', 0, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"eyebrow":"Safety","heading":"Road safety education","lede":"An expressway is faster and safer than an ordinary road — for drivers who treat it differently. Most serious crashes on expressways come from a few avoidable mistakes."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"নিরাপত্তা","heading":"সড়ক নিরাপত্তা শিক্ষা","lede":"এক্সপ্রেসওয়ে সাধারণ সড়কের চেয়ে দ্রুত ও নিরাপদ — যারা এটিকে ভিন্নভাবে ব্যবহার করেন তাদের জন্য। এক্সপ্রেসওয়ের বেশির ভাগ গুরুতর দুর্ঘটনা কয়েকটি এড়ানো সম্ভব ভুল থেকে ঘটে।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"安全","heading":"道路安全教育","lede":"高速公路比普通道路更快、更安全——前提是驾驶人区别对待。高速公路上大多数严重事故源于少数可避免的错误。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'card-grid', 1, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Six habits that prevent crashes","intro":"","items":[{"meta":"1","title":"Keep your distance","body":"At expressway speed a car needs far longer to stop than drivers expect. Leave at least a three-second gap to the vehicle ahead, and more in rain or fog."},{"meta":"2","title":"Keep to the limit","body":"The speed limit is a maximum, not a target. Slow down where signs show a lower limit — at plazas, interchanges and works."},{"meta":"3","title":"Stay awake","body":"Fatigue causes crashes that happen without braking. Stop at a safe place every two hours, and never drive when drowsy."},{"meta":"4","title":"Use lanes properly","body":"Keep left unless overtaking; overtake on the right only; signal early; never weave between lanes."},{"meta":"5","title":"Everyone belted","body":"Every person in the vehicle wears a seat belt, front and back. Children travel in the back."},{"meta":"6","title":"Phone away","body":"Using a hand-held phone while driving is an offence and takes your eyes off the road for seconds that matter."}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"দুর্ঘটনা প্রতিরোধের ছয়টি অভ্যাস","intro":"","items":[{"meta":"১","title":"দূরত্ব বজায় রাখুন","body":"এক্সপ্রেসওয়ের গতিতে গাড়ি থামাতে চালকদের ধারণার চেয়ে অনেক বেশি পথ লাগে। সামনের যানবাহন থেকে কমপক্ষে তিন সেকেন্ডের দূরত্ব রাখুন, বৃষ্টি বা কুয়াশায় আরও বেশি।"},{"meta":"২","title":"গতিসীমা মানুন","body":"গতিসীমা সর্বোচ্চ সীমা, লক্ষ্য নয়। সাইনে কম সীমা দেখানো জায়গায় — প্লাজা, ইন্টারচেঞ্জ ও কাজের এলাকায় — গতি কমান।"},{"meta":"৩","title":"সজাগ থাকুন","body":"ক্লান্তির কারণে এমন দুর্ঘটনা ঘটে যেখানে ব্রেকই চাপা হয় না। প্রতি দুই ঘণ্টায় নিরাপদ জায়গায় থামুন, ঘুম ঘুম ভাব নিয়ে কখনো চালাবেন না।"},{"meta":"৪","title":"লেন সঠিকভাবে ব্যবহার করুন","body":"ওভারটেক ছাড়া বাম দিকে থাকুন; শুধু ডান দিক দিয়ে ওভারটেক করুন; আগে সংকেত দিন; কখনো লেনের মধ্যে এঁকেবেঁকে চালাবেন না।"},{"meta":"৫","title":"সবাই সিটবেল্ট পরুন","body":"গাড়ির সামনে-পেছনে প্রত্যেকে সিটবেল্ট পরবেন। শিশুরা পেছনে বসবে।"},{"meta":"৬","title":"ফোন দূরে রাখুন","body":"গাড়ি চালানোর সময় হাতে ফোন ব্যবহার অপরাধ এবং গুরুত্বপূর্ণ কয়েক সেকেন্ড আপনার চোখ সড়ক থেকে সরিয়ে দেয়।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"预防事故的六个习惯","intro":"","items":[{"meta":"1","title":"保持车距","body":"在高速公路车速下，制动距离远超驾驶人预期。与前车至少保持三秒间隔，雨雾天气应更大。"},{"meta":"2","title":"遵守限速","body":"限速是上限而非目标。在标志显示更低限速的地方——收费站、互通立交和施工区——应减速。"},{"meta":"3","title":"保持清醒","body":"疲劳会导致来不及制动的事故。每两小时在安全地点休息一次，困倦时切勿驾驶。"},{"meta":"4","title":"规范使用车道","body":"除超车外靠左行驶；只从右侧超车；提前打转向灯；切勿频繁变道穿插。"},{"meta":"5","title":"全员系安全带","body":"车内前后排所有人均须系好安全带。儿童乘坐后排。"},{"meta":"6","title":"放下手机","body":"驾驶时手持使用手机属于违法行为，会让您的视线在关键几秒内离开道路。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 2, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Never on an expressway","body":"<ul><li>Never stop on the carriageway, reverse, or make a U-turn.</li><li>Never walk on the carriageway or cross it on foot.</li><li>Never pick up or set down passengers except at a proper bus stop off the expressway.</li><li>Never drive a motorcycle, three-wheeler or non-motorised vehicle onto the toll carriageways.</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"এক্সপ্রেসওয়েতে কখনো নয়","body":"<ul><li>ক্যারেজওয়েতে কখনো থামবেন না, পেছনে যাবেন না বা ইউ-টার্ন নেবেন না।</li><li>ক্যারেজওয়েতে কখনো হাঁটবেন না বা পায়ে হেঁটে পার হবেন না।</li><li>এক্সপ্রেসওয়ের বাইরে নির্ধারিত বাসস্টপ ছাড়া যাত্রী ওঠানামা করাবেন না।</li><li>টোল সড়কে মোটরসাইকেল, থ্রি-হুইলার বা অযান্ত্রিক যানবাহন চালাবেন না।</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"高速公路上绝对禁止","body":"<ul><li>禁止在车道上停车、倒车或掉头。</li><li>禁止在车道上行走或步行横穿。</li><li>禁止在快速路外正规公交站以外的地点上下客。</li><li>禁止驾驶摩托车、三轮车或非机动车驶入收费车道。</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', 3, 'published' FROM DUAL WHERE @fresh = 1;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"For schools and communities","body":"<p>Schools, driver training centres and community groups near the corridor can ask for a road-safety session on crossing safely near the expressway and on expressway driving. Ask through the <a href=\\"contact\\">contact form</a> with the subject “Road safety session”.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"বিদ্যালয় ও জনগোষ্ঠীর জন্য","body":"<p>করিডোরের কাছের বিদ্যালয়, চালক প্রশিক্ষণ কেন্দ্র ও সামাজিক সংগঠন এক্সপ্রেসওয়ের কাছে নিরাপদে পারাপার ও এক্সপ্রেসওয়েতে গাড়ি চালানো নিয়ে সড়ক নিরাপত্তা সেশনের অনুরোধ করতে পারে। <a href=\\"contact\\">যোগাযোগ ফরমে</a> “সড়ক নিরাপত্তা সেশন” বিষয় বেছে অনুরোধ করুন।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"面向学校和社区","body":"<p>走廊附近的学校、驾驶培训机构和社区团体可申请道路安全讲座，内容包括快速路附近安全过街和高速公路驾驶。请通过<a href=\\"contact\\">联系表单</a>选择“道路安全讲座”主题申请。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
