INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"If you are not satisfied with the answer","body":"<p>Every reply names the officer who handled your grievance. If the answer does not resolve it, reply quoting your tracking number and ask for a review by DBEDC''s appeal officer, who was not involved in the first decision; the review is answered within 15 working days.</p><p>You can also lodge a grievance through the Government''s Grievance Redress System at <a href=\\"https://www.grs.gov.bd\\">grs.gov.bd</a>, which reaches the Roads and Highways Department. Land acquisition compensation is handled by the Deputy Commissioner''s office; see <a href=\\"disclosures/land-acquisition\\">land acquisition</a>.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"উত্তরে সন্তুষ্ট না হলে","body":"<p>প্রতিটি উত্তরে আপনার অভিযোগ দেখেছেন এমন কর্মকর্তার নাম থাকে। উত্তরে সমাধান না হলে ট্র্যাকিং নম্বর উল্লেখ করে উত্তর দিন এবং DBEDC-এর আপিল কর্মকর্তার কাছে পুনর্বিবেচনার অনুরোধ করুন, যিনি প্রথম সিদ্ধান্তে যুক্ত ছিলেন না; ১৫ কার্যদিবসের মধ্যে পুনর্বিবেচনার উত্তর দেওয়া হয়।</p><p>সরকারের অভিযোগ প্রতিকার ব্যবস্থার মাধ্যমেও অভিযোগ করতে পারেন: <a href=\\"https://www.grs.gov.bd\\">grs.gov.bd</a>, যা সড়ক ও জনপথ অধিদপ্তরে পৌঁছায়। ভূমি অধিগ্রহণের ক্ষতিপূরণ জেলা প্রশাসকের কার্যালয় দেখে; দেখুন <a href=\\"disclosures/land-acquisition\\">ভূমি অধিগ্রহণ</a>।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"如对答复不满意","body":"<p>每份答复都会注明处理您投诉的官员。若答复未能解决问题，请引用跟踪编号回复，申请由未参与初次决定的DBEDC申诉官员复核；复核在15个工作日内答复。</p><p>您也可以通过政府投诉处理系统<a href=\\"https://www.grs.gov.bd\\">grs.gov.bd</a>提交投诉，该系统直达孟加拉国公路局。征地补偿由县专员办公室负责，详见<a href=\\"disclosures/land-acquisition\\">征地</a>。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'rich-text', IF(@endcta = 1, @lastsort, COALESCE(@lastsort, 0) + 1), 'published' FROM DUAL WHERE @ok;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"How this website is tested","body":"<p>The pages road users rely on — the home page, toll rates and the fare calculator, the corridor map, traffic status, route, rules, contact, grievances and search — are tested automatically against WCAG 2.1 level AA with the axe-core rule set, in English, Bangla and Chinese, before every release. A release with a serious or critical failure is not published.</p><p>Automated testing finds only part of real barriers. Known limits: the corridor map is a visual diagram, and the same information is given as a table beside it; documents uploaded as PDFs may not all be tagged for screen readers. If you meet a barrier, tell us through the <a href=\\"contact\\">contact form</a> and it will be answered within 10 working days.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"এই ওয়েবসাইট কীভাবে পরীক্ষা করা হয়","body":"<p>সড়ক ব্যবহারকারীরা যেসব পাতার ওপর নির্ভর করেন — হোম পেজ, টোল হার ও ভাড়া হিসাবকারী, করিডোরের মানচিত্র, যান চলাচলের অবস্থা, রুট, সড়ক বিধি, যোগাযোগ, অভিযোগ ও অনুসন্ধান — প্রতিটি রিলিজের আগে ইংরেজি, বাংলা ও চীনা ভাষায় axe-core নিয়মাবলি দিয়ে WCAG 2.1 AA মানে স্বয়ংক্রিয়ভাবে পরীক্ষা করা হয়। গুরুতর বা সংকটপূর্ণ ত্রুটিসহ কোনো রিলিজ প্রকাশ করা হয় না।</p><p>স্বয়ংক্রিয় পরীক্ষা বাস্তব বাধার একটি অংশই খুঁজে পায়। জানা সীমাবদ্ধতা: করিডোরের মানচিত্র একটি দৃশ্যমান চিত্র, একই তথ্য পাশে সারণিতে দেওয়া আছে; PDF হিসেবে আপলোড করা সব নথি স্ক্রিন রিডারের জন্য ট্যাগ করা না-ও থাকতে পারে। কোনো বাধার সম্মুখীন হলে <a href=\\"contact\\">যোগাযোগ ফরমে</a> জানান, ১০ কার্যদিবসের মধ্যে উত্তর দেওয়া হবে।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"本网站如何测试","body":"<p>道路使用者依赖的页面——首页、通行费标准和费用计算器、走廊地图、交通状况、路线、道路规则、联系、投诉和搜索——在每次发布前均以英文、孟加拉文和中文，使用axe-core规则集按WCAG 2.1 AA级进行自动测试。存在严重或关键问题的版本不予发布。</p><p>自动测试只能发现部分实际障碍。已知局限：走廊地图为可视化图示，旁边以表格形式提供相同信息；以PDF上传的文件可能并非全部带有屏幕阅读器标签。如遇访问障碍，请通过<a href=\\"contact\\">联系表单</a>告知，我们将在10个工作日内答复。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `schema_migrations` (`name`) VALUES ('34-remaining-pages');
