-- ---------------------------------------------------------------- addition to grievances
SET @p = (SELECT `id` FROM `pages` WHERE `slug` = 'grievances');
SET @has = (SELECT COUNT(*) FROM `blocks` b JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en' WHERE b.`page_id` = @p AND CAST(t.`data` AS CHAR) LIKE '%grs.gov.bd%');
SET @ok = (@p IS NOT NULL AND @has = 0);
SET @last = (SELECT `id` FROM `blocks` WHERE `page_id` = @p ORDER BY `sort_order` DESC, `id` DESC LIMIT 1);
SET @lastsort = (SELECT `sort_order` FROM `blocks` WHERE `id` = @last);
SET @endcta = (SELECT `type` = 'cta-band' FROM `blocks` WHERE `id` = @last);
UPDATE `blocks` SET `sort_order` = `sort_order` + 1 WHERE `id` = @last AND @ok AND @endcta = 1;
SET @b = IF(@ok, LAST_INSERT_ID(), NULL);

-- ---------------------------------------------------------------- addition to accessibility
SET @p = (SELECT `id` FROM `pages` WHERE `slug` = 'accessibility');
SET @has = (SELECT COUNT(*) FROM `blocks` b JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en' WHERE b.`page_id` = @p AND CAST(t.`data` AS CHAR) LIKE '%axe-core%');
SET @ok = (@p IS NOT NULL AND @has = 0);
SET @last = (SELECT `id` FROM `blocks` WHERE `page_id` = @p ORDER BY `sort_order` DESC, `id` DESC LIMIT 1);
SET @lastsort = (SELECT `sort_order` FROM `blocks` WHERE `id` = @last);
SET @endcta = (SELECT `type` = 'cta-band' FROM `blocks` WHERE `id` = @last);
UPDATE `blocks` SET `sort_order` = `sort_order` + 1 WHERE `id` = @last AND @ok AND @endcta = 1;
SET @b = IF(@ok, LAST_INSERT_ID(), NULL);

